INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000198', '天弘余额宝', '货币市场型基金', 679946059599.32, '2013-05-29', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金根据对短期利率变动的预测,采用投资组合平均剩余期限控制下的主动性投资策略,利用定性分析和定量分析方法,通过对短期金融工具的积极投资,在控制风险和保证流动性的基础上,力争获得稳定的当期收益。 1、资产配置策略 本基金通过对宏观经济形势、财政与货币政策、金融监管政策、市场结构变化和短期资金供给等因素的分析,形成对未来短期利率走势的判断。在此基础上,根据不同类别资产的收益率水平(各剩余期限到期收益率、利息支付方式和再投资便利性),并结合各类资产的流动性特征(日均成交量、交易方式、市场流量)和风险特征(信用等级、波动性),决定各类资产的配置比例和期限匹配量。 2、个券选择策略 本基金将优先考虑安全性因素,选择央票、短期国债等高信用等级的债券品种进行投资以规避风险。在基金投资的个券选择上,本基金首先将各券种的信用等级、剩余期限和流动性(日均成交量和平均每笔成交间隔时间)进行初步筛选;然后,根据各券种的收益率与剩余期限的结构合理性,评估其投资价值,进行再次筛选;最后,根据各券种的到期收益率波动性与可投资量(流通量、日均成交量与冲击成本估算),决定具体投资比例。 3、久期策略 本基金根据对未来短期利率走势的研判,结合货币市场基金资产的高流动性要求及其相关的投资比例规定,动态调整组合的久期。当预期市场短期利率上升时,本基金将通过增加持有剩余期限较短债券并减持剩余期限较长债券等方式降低组合久期,以降低组合跌价风险;当预期市场短期利率下降时,则通过增持剩余期限较长的债券等方式提高组合久期,以分享债券价格上升的收益。 4、回购策略 根据回购市场利率走势变化情况,在回购利率较低时,本基金在严格遵守相关法律法规的前提下,利用正回购操作循环融入资金进行债券投资,提高基金收益水平。 另一方面,本基金将把握资金供求的瞬时效应,积极捕捉收益率峰值的短线机会。如新股发行期间、年末资金回笼时期的季节效应等短期资金供求失衡,导致回购利率突增等。此时,本基金可通过逆回购的方式融出资金以分享短期资金拆借利率陡升的投资机会。 5、套利策略 不同交易市场或不同交易品种受参与群体、交易模式、环境冲击、流动性等因素影响而出现定价差异,从而产生套利机会。本基金在充分论证这种套利机会可行性的基础上,适度进行跨市场或跨品种套利操作,提高资产收益率。如跨银行间和交易所的跨市场套利,期限收益结构偏移中的不同期限品种的互换操作(跨期限套利)。 6、现金流管理策略 本基金作为现金管理工具,具有较高的流动性要求,本基金将根据对市场资金面分析以及对申购赎回变化的动态预测,通过回购的滚动操作和债券品种的期限结构搭配,动态调整并有效分配基金的现金流,在保持充分流动性的基础上争取较高收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000686', '建信嘉薪宝A', '货币市场型基金', 396043222796.09, '2014-06-17', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采取个券选择策略、利率策略等积极投资策略,在严格控制风险的前提下,发掘和利用市场失衡提供的投资机会,实现组合增值。 1、资产配置策略基金根据宏观经济运行状况、政策形势、信用状况、利率走势、资金供求变化等的综合判断,并结合各类资产的流动性特征、风险收益、估值水平特征,决定基金资产在债券、银行存款等各类资产的配置比例,并适时进行动态调整。 2、个券选择策略在个券选择上,基金将综合运用收益率曲线分析、流动性分析、信用风险分析等方法来评估个券的投资价值,发掘出具备相对价值的个券。 3、利率策略通过全面研究 GDP、物价、就业以及国际收支等主要经济变量,分析宏观经济运行的可能情景,并预测财政政策、货币政策等宏观经济政策取向,分析金融市场资金供求状况变化趋势及结构。在此基础上,预测金融市场利率水平变动趋势,以及金融市场收益率曲线斜度变化趋势。 4、利用短期市场机会的灵活策略由于市场分割、信息不对称、发行人信用等级意外变化等情况会造成短期内市场失衡;新股、新债发行以及年末效应等因素会使市场资金供求发生短时的失衡。这种失衡将带来一定市场机会。通过分析短期市场机会发生的动因,研究其中的规律,据此调整组合配置,改进操作方法,积极利用市场机会获得超额收益。未来,随着证券市场投资工具的发展和丰富,本基金可相应调整和更新相关投资策略,并在招募说明书更新中公告。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000343', '华夏财富宝A', '货币市场型基金', 323708609954.27, '2013-10-25', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1、资产配置策略基金根据宏观经济运行状况、政策形势、信用状况、利率走势、资金供求变化等的综合判断,并结合各类资产的流动性特征、风险收益、估值水平特征,决定基金资产在债券、银行存款等各类资产的配置比例,并适时进行动态调整。 2、个券选择策略在个券选择上,基金将综合运用收益率曲线分析、流动性分析、信用风险分析等方法来评估个券的投资价值,发掘出具备相对价值的个券。 3、银行存款投资策略基金根据不同银行的银行存款收益率情况,结合银行的信用等级、存款期限等因素的分析,以及对整体利率市场环境及其变动趋势的研究,在严格控制风险的前提下选择具有较高投资价值的银行存款进行投资。 4、利用短期市场机会的灵活策略由于市场分割、信息不对称、发行人信用等级意外变化等情况会造成短期内市场失衡;新股、新债发行以及年末效应等因素会使市场资金供求发生短时的失衡。这种失衡将带来一定市场机会。通过分析短期市场机会发生的动因,研究其中的规律,据此调整组合配置,改进操作方法,积极利用市场机会获得超额收益。未来,随着证券市场投资工具的发展和丰富,本基金可相应调整和更新相关投资策略,并在招募说明书更新中公告。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000359', '易方达易理财A', '货币市场型基金', 297324758461.21, '2013-10-24', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金利用定性分析和定量分析方法,通过对短期金融工具的积极投资,在有效控制投资风险和保持高流动性的基础上,力争获得高于业绩比较基准的投资回报。1、资产配置策略基金管理人根据市场情况和可投资品种的容量,在严谨深入的研究分析基础上,综合考量市场资金面走向、存款银行的信用资质、信用债券的信用评级以及各类资产的收益率水平、流动性特征等,确定各类资产的配置比例。2、杠杆投资策略本基金将对回购利率与短期债券收益率、存款利率进行比较,并在对资金面进行综合分析的基础上,判断利差套利空间,并确定杠杆操作策略。3、银行存款及同业存单投资策略本基金在向交易对手银行进行询价的基础上,选取利率报价较高的银行进行存款投资,在投资过程中基于对交易对手信用风险的评估,选择交易对手。当银行存款投资具有较高投资价值时,本基金存款投资比例上限最高可达100%。4、债券回购投资策略本基金基于对资金面走势的判断,选择回购品种和期限。若资产配置中有逆回购,则在判断资金面趋于宽松的情况下,优先进行相对较长期限逆回购配置;反之,则进行相对较短期限逆回购操作。在组合进行杠杆操作时,根据资金面的松紧,决定正回购的操作期限。5、利率品种的投资策略本基金对国债、央行票据等利率品种的投资,是在对国内、国外经济趋势进行分析和预测基础上,运用数量方法,对利率期限结构变化趋势和债券市场供求关系变化进行分析和预测,深入分析利率品种的收益和风险,并据此调整债券组合的平均久期。在确定组合平均久期后,本基金对债券的期限结构进行分析,运用统计和数量分析技术,选择合适的期限结构配置策略,在合理控制风险的前提下,综合考虑组合的流动性,决定投资品种。6、信用品种的投资策略基金管理人通过“内部信用评级体系”对市场公开发行的短期融资券、中期票据、企业债、公司债和可分离转债存债等信用品种进行研究和筛选,形成信用债券投资备选库。在信用债券投资备选库基础上,结合本基金的投资与配置需要,通过分析比较到期收益率、剩余期限、流动性等特征,挑选适当的短期信用品种进行投资。7、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向。当监管机构允许基金参与此类金融工具的投资,本基金将按照届时生效的法律法规,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000719', '南方现金通E', '货币市场型基金', 252899034420.73, '2014-07-02', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采用积极管理型的投资策略,在控制利率风险、尽量降低基金净值波动风险并满足流动性的前提下,提高基金收益。 1、利率策略本基金将首先采用“自上而下”的研究方法,综合研究主要经济变量指标、分析宏观经济情况,建立经济前景的情景模拟,进而判断财政政策、货币政策等宏观经济政策取向。同时,本基金还将分析金融市场资金供求状况变化趋势,对影响资金面的因素进行详细分析与预判,建立资金面的场景模拟。在宏观分析与流动性分析的基础上,结合历史与经验数据,确定当前资金的时间价值、通货膨胀补偿、流动性溢价等要素,得到当前宏观与流动性条件下的均衡收益率曲线。区分当前利率债收益率曲线期限利差、曲率与券间利差所面临的历史分位,然后通过市场收益率曲线与均衡收益率曲线的对比,判断收益率曲线参数变动的程度和概率,确定组合的平均剩余期限,并据此动态调整投资组合。 2、骑乘策略当市场利率期限结构向上倾斜并且相对较陡时,投资并持有债券一段时间,随着时间推移,债券剩余年限减少,市场同样年限的债券收益率较低,这时将债券按市场价格出售,投资人除了获得债券利息以外,还可以获得资本利得。在多数情况下,这样的骑乘操作策略可以获得比持有到期更高的收益。 3、放大策略放大策略即以组合现有债券为基础,利用买断式回购、质押式回购等方式融入资金,并购买剩余年限相对较长的债券,以期获取超额收益的操作方式。在回购利率过高、流动性不足、或者市场状况不宜采用放大策略等情况下,本基金将适时降低杠杆投资比例。 4、信用债投资策略 (1)信用风险控制。本基金拟投资的每支信用债券必需经过南方基金债券信用评级系统进行内部评级,符合基金所对应的内部评级规定的方可进行投资,以事前防范和控制信用风险。 (2)信用利差策略。信用产品相对国债、政策性金融债等利率产品的信用利差是获取较高投资收益的来源。首先,伴随经济周期的波动,在经济周期上行或下行阶段,信用利差通常会缩小或扩大,利差的变动会带来趋势性的信用产品投资机会。同时,研究不同行业在经济周期和政策变动中所受的影响,以确定不同行业总体信用风险和利差水平的变动情况,投资具有积极因素的行业,规避具有潜在风险的行业。其次,信用产品发行人资信水平和评级调整的变化会使产品的信用利差扩大或缩小,本基金将充分发挥内部评级在定价方面的作用,选择评级有上调可能的信用债,以获取因利差下降带来的价差收益。第三,对信用利差期限结构进行研究,分析各期限信用债利差水平相对历史平均水平所处的位置,以及不同期限之间利差的相对水平,发现更具投资价值的期限进行投资;第四,研究分析相同期限但不同信用评级债券的相对利差水平,发现偏离均值较多、相对利差有收窄可能的债券。 (3)类属选择策略。国内信用产品目前正经历着快速发展阶段,不同审批机构批准发行的信用产品在定价、产品价格特性、信用风险方面具有一定差别,本基金将考虑产品定价的合理性、产品主要投资人的需求特征、不同类属产品的持有收益和价差收益特点和实际信用风险状况,进行信用债券的类属选择。 5、资产支持证券投资策略当前国内资产支持证券市场以信贷资产证券化产品为主(包括以银行贷款资产、住房抵押贷款等作为基础资产),仍处于创新试点阶段。产品投资关键在于对基础资产质量及未来现金流的分析,本基金将在国内资产证券化产品具体政策框架下,采用基本面分析和数量化模型相结合,对个券进行风险分析和价值评估后进行投资。本基金将严格控制资产支持证券的总体投资规模并进行分散投资,以降低流动性风险。 6、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向,一旦监管机构允许基金参与此类金融工具的投资,本基金将在届时相应法律法规的框架内,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000638', '富国富钱包A', '货币市场型基金', 248673935240.1, '2014-05-07', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采用积极管理型的投资策略,将投资组合的平均剩余期限控制在120天以内,在控制利率风险、尽量降低基金净值波动风险并满足流动性的前提下,提高基金收益。在投资管理过程中,基金管理人将基于“定性与定量相结合、保守与积极相结合”的原则,根据短期利率的变动和市场格局的变化,采用投资组合平均剩余期限控制下的主动性投资策略。具体包括: 1、总体资产配置策略 (1)利率预期分析基于对国家宏观政策(包括:财政政策、货币政策等)的深入研究以及对央行公开市场操作、资金供求、资金流动性、货币市场与资本市场的资金互动、市场成员特征等因素的客观分析,合理预期利率变化趋势,并据此确定投资组合的总体资产配置策略。 (2)投资组合平均剩余期限控制结合宏观经济和利率预期分析,在合理运用量化模型的基础上,动态确定并控制投资组合的平均剩余期限。具体而言,在预计市场利率上升时,适度缩短投资组合的平均剩余期限;在预计利率下降时,适度延长投资组合的平均剩余期限。 2、类别资产配置策略本基金以短期金融工具作为投资对象,基于对各细分市场的市场规模、交易情况、各交易品种的流动性、相对收益、信用风险以及投资组合平均剩余期限要求等重要指标的分析,确定(调整)投资组合的类别资产配置比例。对于含回售条款的债券,本基金将仅买入距回售日不超过397天以内的债券,并在回售日前进行回售或者卖出。 3、明细资产选择和交易策略 (1)收益率曲线分析策略根据债券市场收益率曲线的动态变化以及隐含的即期利率和远期利率提供的价值判断基础,结合对当期和远期资金面的分析,寻求在一段时期内获取因收益率曲线变化而导致的债券价格变化所产生的超额收益。本基金将比较分析子弹策略、哑铃策略和梯子策略等在不同市场环境下的表现,构建优化组合,获取较高收益。 (2)套利操作策略 1)跨市场套利策略短期资金市场由交易所市场和银行间市场构成。由于其中的投资群体、交易方式等市场要素不同,使得两个市场的资金面、短期利率期限结构、流动性都存在着一定的差别。本基金将在充分论证套利机会可行性的基础上,寻找合理的介入时机,进行跨市场套利操作。 2)跨品种套利策略由于投资群体存在一定的差异性,对期限相近的交易品种同样可能因为存在流动性、税收等市场因素的影响出现内在价值明显偏离的情况。本基金将在保证高流动性的基础上进行跨品种套利操作,以增加超额收益。 (3)正回购放大操作策略当预期市场利率下跌或者利率走势平稳时,通过将剩余期限相对较长的短期债券进行正回购质押,融资后再购买短期债券。在融资成本低于短期债券收益率时,该投资策略的运用可实现正收益。 (4)滚动配置策略根据具体投资品种的市场特征,采用持续滚动投资方法,以提高投资组合的整体持续变现能力。 (5)债券相对价值判断策略基于量化模型的分析结果,识别出被市场错误定价的债券,进而采取适当的交易以获得收益。一方面,可通过利率期限结构分析,在现金流特征相近且处于同一风险等级的多只债券品种中寻找更具投资价值的品种;另一方面,通过对债券等级、债券息票率、所在行业特征等因素的分析,评估判断短期风险债券与无风险短期债券间的合理息差。 (6)波动性交易策略根据市场利率的波动性特征,利用关键市场时机(例如:季节性因素、突发事件)造成的短期市场失衡机会进行短期交易,以获得超额收益。 (7)流动性管理策略根据对市场资金面分析以及对申购、赎回变化的动态预测,通过现金库存管理、回购的滚动操作和债券品种的期限结构搭配,动态调整并有效分配基金的现金流,在保持本基金资产充分流动性的基础上,确保稳定收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000569', '鹏华增值宝', '货币市场型基金', 228563354240.67, '2014-02-26', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将综合宏观经济运行状况,货币政策、财政政策等政府宏观经济状况及政策,分析资本市场资金供给状况的变动趋势,预测市场利率水平变动趋势。在此基础上,综合考虑各类投资品种的流动性、收益性以及信用风险状况,进行积极的投资组合管理。 1、久期策略结合宏观经济运行态势及利率预测分析,本基金将动态确定并调整基金组合平均剩余期限。预测利率将进入下降通道时,适当延长投资品种的平均期限;预测市场利率将进入上升通道时,适当缩短投资品种的平均期限。 2、类属配置策略在保证流动性的前提下,根据各类货币市场工具的市场规模、信用等级、流动性、市场供求、票息及付息频率等确定不同类别资产的具体配置比例。 3、套利策略本基金根据对货币市场变动趋势、各市场和品种之间的风险收益差异的充分研究和论证,适当进行跨市场或跨品种套利操作,力争提高资产收益率,具体策略包括跨市场套利和跨期限套利等。 4、现金管理策略本基金作为现金管理工具,具有较高的流动性要求,本基金将根据对市场资金面分析以及对申购赎回变化的动态预测,通过回购的滚动操作和债券品种的期限结构搭配,动态调整并有效分配基金的现金流,在保持充分流动性的基础上争取较高收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000397', '汇添富全额宝A', '货币市场型基金', 222052414017.58, '2013-12-13', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将结合宏观分析和微观分析制定投资策略,力求在满足安全性、流动性需要的基础上实现更高的收益率。 1、本基金的投资策略将基于以下研究分析: (1)市场利率研究 A、宏观经济趋势宏观经济状况是央行制定货币政策的基础,也是影响经济总体货币需求的关键因素,因此宏观经济趋势基本上确定了未来较长时期内的利率水平。在分析宏观经济趋势时,本基金重点关注两个因素。一是经济增长前景;二是通货膨胀率及其预期。 B、央行的货币政策取向包括基准存、贷款利率,法定存款准备金率,公开市场操作的方向、力度,以及央行的窗口指导等。央行的货币政策取向是影响货币市场利率的最直接因素。在央行紧缩货币、提高基准利率时,市场利率一般会相应上升;而央行放松货币、降低基准利率时,市场利率则相应下降。 C、商业银行的信贷扩张商业银行的信贷扩张是央行实现其货币政策目标的重要途径,也是经济总体货币需求的体现。因此商业银行的信贷扩张对货币市场利率具有举足轻重的影响。一般来说,商业银行信贷扩张越快,表明经济总体的货币需求越旺盛,货币市场利率也越高;反之,信贷扩张越慢,货币市场利率也越低。 D、国际资本流动中国日益成为一个开放的国家,国际资本进出也更加频繁,并导致央行被动的投放或收回基础货币,造成货币市场利率的波动。在人民币汇率制度已经从钉住美元转为以市场供求为基础、参考一篮子货币进行调节、有管理的浮动汇率制度的情况下,国际资本流动对国内市场利率的影响也越发重要。 E、其他影响短期资金供求关系的因素包括财政存款的短期变化,市场季节性、突发性的资金需求等。 (2)市场结构研究银行间市场与交易所市场在资金供给者和需求者结构上均存在差异,利率水平因此有所不同。不同类型市场工具由于存在税负、流动性、信用风险上的差异,其收益率水平也略有不同。资金供给者、需求者结构的变化也会引起利率水平的变化。积极利用这些利率差异、利率变化就可能在保证流动性、安全性的基础上为基金资产带来更高的收益率。 (3)企业信用分析直接融资的发展是一个长期趋势,企业债、企业短期融资券因此也将成为货币市场基金重要的投资对象。为了保障基金资产的安全,本基金将按照相关法规仅投资于具有满足信用等级要求的企业债券、短期融资券。与此同时,本基金还将深入分析发行人的财务稳健性,判断发行人违约的可能性,严格控制企业债券、短期融资券的违约风险。 2、本基金具体投资策略 (1)滚动配置策略本基金将根据具体投资品种的市场特性采用持续投资的方法,既能提高基金资产变现能力的稳定性,又能保证基金资产收益率与市场利率的基本一致。 (2)久期控制策略本基金将根据对货币市场利率趋势的判断来配置基金资产的久期。在预期利率上升时,缩短基金资产的久期,以规避资本损失或获得较高的再投资收益;在预期利率下降时,延长基金资产的久期,以获取资本利得或锁定较高的收益率。 (3)套利策略套利策略包括跨市场套利和跨品种套利。跨市场套利是利用同一金融工具在各个子市场的不同表现进行套利。跨品种套利是利用不同金融工具的收益率差别,在满足基金自身流动性、安全性需要的基础上寻求更高的收益率。 (4)时机选择策略股票、债券发行以及年末效应等因素可能会使市场资金供求情况发生暂时失衡,从而推高市场利率。充分利用这种失衡就能提高基金资产的收益率。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000379', '平安日增利A', '货币市场型基金', 217668452843.69, '2013-12-03', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金根据对未来短期利率变动的预测,确定和调整基金投资组合的平均剩余期限。对各类投资品种进行定性分析和定量分析方法,确定和调整参与的投资品种和各类投资品种的配置比例。在严格控制投资风险和保持资产流动性的基础上,力争获得稳定的当期收益。 1、整体资产配置策略本基金通过对宏观经济形势、财政与货币政策、金融监管政策、短期资金市场状况等因素的分析,综合判断未来短期利率变动,对投资组合的平均剩余期限进行控制。 (1)利率预期分析通过对通货膨胀、GDP、货币供应量、国际利率水平、金融监管政策取向等跟踪分析,形成对基本面的宏观研判。同时,结合微观层面研究,主要考察指标包括:央行公开市场操作、主要机构投资者的短期投资倾向、债券供给、回购抵押数量等,合理预期货币市场利率曲线动态变化。 (2)动态调整投资组合平均剩余期限 根据利率预期分析,动态确定并控制投资组合平均剩余期限在120天以内。当市场利率看涨时,适度缩短投资组合平均剩余期限,即减持剩余期限较长投资品种增持剩余期限较短品种,降低组合整体净值损失风险;当市场看跌时,则相对延长投资组合平均剩余期限,增持较长剩余期限的投资品种,获取超额收益。 2、类属资产配置策略类属资产配置指投资组合在各类投资品种如央行票据、国债、金融债、企业短期融资券以及现金等投资品种之间的配置比例。作为现金管理工具本基金将根据各类投资品种的流动性、收益性和风险特征,利用定性分析和定量分析方法,决定参与的投资品种和各类投资品种的配置比例及投资品种期限组合。 (1)流动性分析通过对市场资金面、基金申购赎回金额的变化进行动态分析,确定本基金的流动性目标。在此基础上,基金管理人在高流动性资产和相对流动性较低资产之间寻找平衡,以满足组合的日常流动性需求。 (2)收益-风险分析 通过分析各类投资品种的相对收益、利差变化、市场容量、信用等级情况、流动性风险、信用风险等因素来确定配置比例和期限组合,寻找具有投资价值的投资品种,增持相对低估、价格将上升的,能给组合带来相对较高回报的类属;减持相对高估、价格将下降的,给组合带来相对较低回报的类属,借以取得较高的总回报。 3、个券选择策略在个券选择层面,本基金将首先从安全性角度出发,优先选择央票、短期国债等高信用等级的债券品种以规避信用违约风险。对于信用评级等级较高(符合法规规定的级别)的企业债、短期融资券等信用类债券,本基金也可以进行配置。除考虑安全性因素外,在具体的券种选择上,基金管理人将遵循以下原则: (1)根据明细资产的剩余期限、资信等级、流动性指标(流通总量、日均交易量),决定是否纳入组合; (2)根据个别债券的收益率(到期收益率、票面利率、利息支付方式、利息税务处理)与剩余期限的配比,对照基金的收益要求决定是否纳入组合; (3)根据个别债券的流动性指标(发行总量、流通量、上市时间),决定投资总量。 (4)若出现因市场原因所导致的收益率高于公允水平,则该券种价格出现低估,本基金将对此类低估品种进行重点关注。 4、流动性管理策略本基金作为现金管理工具,必须具备较高的流动性。基金管理人在密切关注基金的申购赎回情况、季节性资金流动情况和日历效应等因素基础上,对投资组合的现金比例进行优化管理。基金管理人将在遵循流动性优先的原则下,综合平衡基金资产在流动性资产和收益性资产之间的配置比例,通过现金留存、持有高流动性券种、正向回购、降低组合久期等方式提高基金资产整体的流动性,以满足日常的基金资产变现需求。 5、套利策略由于市场环境差异、交易市场分割、市场参与者差异,以及资金供求失衡导致的中短期利率异常差异,使得债券现券市场上存在着套利机会。本基金通过分析货币市场变动趋势、各市场和品种之间的风险收益差异,把握无风险套利机会,包括银行间和交易所市场出现的跨市场套利机会、在充分论证套利可行性的基础上的跨期限套利等。基金管理人将在保证基金的安全性和流动性的前提下,适当参与市场的套利,捕捉和把握无风险套利机会,进行跨市场、跨品种操作,以期获得安全的超额收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('004717', '万家天添宝货币A', '货币市场型基金', 216376830546.46, '2017-07-28', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金在投资组合的管理中，将通过市场利率预期策略、久期管理策略、类属资产配置策略、个券选择策略、同业存单投资策略、回购策略、套利策略、现金流管理策略和资产支持策略构建投资组合，谋求在满足流动性要求、控制风险的前提下，实现基金收益的最大化。INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000575', '兴全添利宝', '货币市场型基金', 213041273319.73, '2014-02-27', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '根据宏观形势、利率走势等因素,确定各个阶段的投资组合平均久期、剩余期限等指标,并在这些指标要求的基础上构建投资组合;进行主动投资,有效提高资产组合收益。本基金综合运用类属配置、目标久期控制、收益曲线、个券选择、套利等多种投资策略进行投资: (1)类属配置策略类属配置指组合在央行票据、债券回购、短期债券以及现金等投资品种之间的配置比例。本基金通过分析各类属的相对收益、利差变化、流动性风险、信用风险等因素来确定类属配置比例,寻找具有投资价值的投资品种,增持相对低估、价格将上升的,能给组合带来相对较高回报的类属;减持相对高估、价格将下降的,给组合带来相对较低回报的类属,借以取得较高的总回报。 (2)目标久期控制和流动性管理策略本基金采用目标久期控制策略,根据对宏观环境中的市场、气氛和未来利率变动趋势的判断,深入分析收益率曲线与资金供求状况,确定并控制投资组合平均剩余期限,本基金的平均剩余期限控制在120天之内。如果预测利率将上升,可以适当降低组合的目标久期;如果预测利率将下降,则可以适当增加组合的目标久期。并通过控制同业存款的比例、保留充足的可变现资产和平均安排回购到期期限,保证组合的一定流动性。 (3)收益曲线策略收益曲线策略即在不同期限投资品种之间进行的配置,通过考察收益率曲线的动态变化及预期变化,寻求在一段时期内获取因收益率曲线形状变化而导致的债券价格变化所产生的超额收益。在期限配置方面,将在久期决策的基础上,在不增加总体利率风险的情况下,集中于决定期限利差变化的因素,从不同期限的债券的相对价值变化中实现超额收益。 (4)个券选择策略本基金认为普通债券,包括国债、金融债和企业债的估值,主要基于收益率曲线的拟合。在正确拟合收益率曲线的基础上,及时发现偏离市场收益率的债券,并帮助找出这些债券价格偏离的原因,同时,基于收益率曲线可以判断出定价偏高或偏低的期限段,从而指导相对价值投资,选择投资于定价低估的短期债券品种。 (5)套利策略由于市场环境差异、交易市场分割、市场参与者差异,以及资金供求失衡导致的中短期利率异常差异,使得债券现券市场和回购市场上存在着套利机会。无风险套利主要包括银行间市场、交易所市场的跨市场套利和同一交易市场中不同品种的跨品种套利。本基金在保证投资组合流动性的前提下,积极捕捉和把握无风险套利机会。寻找最佳时机,进行跨市场、跨品种操作,获得安全的超额收益。 (6)回购策略本基金将根据对市场走势的判断,合理选择恰当的回购策略,以实现本基金资产的增值。通过回购可以进行放大,在市场上升的时候增加获取收益的能力,并利用买入——回购融资——再投资的机制放大资金使用效率,有机会博取更大的差价收益。在市场下跌时,则可使用买断式回购策略以规避风险。 (7)投资组合的优化配置本基金将运用“兴全货币市场投资组合优化模型”对类属资产和整个投资组合进行优化配置,即在类属资产和整体投资组合久期控制的条件下追求最高的投资收益率。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000539', '中银活期宝A', '货币市场型基金', 190047409207.48, '2014-02-14', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金通过综合考虑各类资产的收益性、流动性和风险特征,根据定量和定性方法,在保持投资组合较低风险和良好流动性的基础上,力争获得高于业绩比较基准的稳定投资回报。 1、资产配置策略本基金将根据市场情况和可投资品种的容量,在严谨深入的研究分析基础上,综合考量市场资金面走向、存款银行的信用资质以及各类资产的收益率水平、流动性特征等,确定各类资产的配置比例。 2、久期控制策略本基金根据对宏观经济和短期资金市场的利率走势,确定投资组合的平均剩余到期期限。具体而言,在预计市场利率上升时,适当缩短投资品种的平均期限以规避资本损失或获得较高的再投资收益;在预计利率下降时,适当延长投资品种的平均期限,以获取资本利得或锁定较高的收益。 3、银行定期存款及大额存单投资策略本基金在向交易对手银行进行询价的基础上,选取利率报价较高的银行进行存款投资,在投资过程中注重对交易对手信用风险的评估和选择,在严格控制风险的前提下决定各银行存款及大额存单的投资比例。 4、短期信用类债券投资策略本基金通过建立“内部信用评级体系”对市场公开发行的所有短期融资券、中期票据、企业债、公司债、可分离转债存债等信用品种进行研究和筛选,形成信用债券投资备选库。结合本基金的投资与配置需要,通过对到期收益率、剩余期限、流动性特征等进行分析比较,挑选适当的短期信用品种进行投资。 5、债券回购投资策略本基金基于对资金面走势的判断,选择回购品种和期限。当回购利率低于债券收益率时,采用息差放大策略,该策略的基本模式是利用已买入债券进行正回购,再利用回购融入资金购买收益率较高债券品种,如此循环至回购期结束卖出债券偿还所融入资金。在进行回购放大操作时,基金管理人将严格遵守相关法律法规关于债券正回购的有关规定。当回购利率高于债券收益率时,本基金将通过逆回购的方式融出资金以分享短期资金利率陡升的投资机会。 6、资产支持证券投资策略本基金管理人通过考量宏观经济形势、提前偿还率、违约率、资产池结构以及资产池资产所在行业景气情况等因素,预判资产池未来现金流变动;研究标的证券发行条款,预测提前偿还率变化对标的证券平均久期及收益率曲线的影响,同时密切关注流动性变化对标的证券收益率的影响,在严格控制信用风险暴露程度的前提下,通过信用研究和流动性管理,选择风险调整后收益较高的品种进行投资。 7、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向,一旦监管机构允许基金参与此类金融工具的投资,本基金将在届时相应法律法规的框架内,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('001010', '易方达增金宝A', '货币市场型基金', 165791950159.32, '2015-01-20', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将对基金资产组合进行积极管理,在深入研究国内外的宏观经济走势、货币政策变化趋势、市场资金供求状况的基础上,综合考虑各类投资品种的收益性、流动性和风险特征,力争获得高于业绩比较基准的投资回报。1、银行存款及同业存单投资策略银行存款及同业存单是本基金重要的投资对象。对于银行存款及同业存单的投资，本基金根据宏观经济指标分析债券类资产和银行存款的预期收益率水平，制定和调整银行存款及同业存单投资比例、存款期限等。2、利率品种的投资策略本基金对利率品种的投资,是在对国内、国外经济趋势进行分析和预测基础上,结合利率期限结构变化趋势和债券市场供求关系变化,据此确定组合的平均久期。在确定组合平均久期后,本基金对债券的期限结构进行分析,选择合适的期限结构配置策略,在合理控制风险的前提下,综合考虑组合的流动性,决定投资品种。3、信用品种的投资策略本基金根据基金管理人的“内部信用评级体系”,从市场上公开发行的信用债券中筛选投资备选券,形成信用债券投资备选库。从信用债券投资备选库中,本基金管理人结合本基金的投资与配置需要,通过分析比较到期收益率、剩余期限、流动性等特征,挑选适当的信用债券进行投资。对于证券公司短期公司债券,在基金管理人的“内部信用评级体系”中,对可选的证券公司短期公司债券品种进行筛选,综合考虑和分析发行主体的公司背景、竞争地位、治理结构、盈利能力、偿债能力、债券收益率等要素,确定投资决策。本基金将对拟投资或已投资的证券公司短期公司债券进行流动性分析和监测,尽量选择流动性相对较好的品种进行投资,并适当控制债券投资组合整体的久期,保证本基金的流动性。为防范大额赎回可能引发的流动性风险,本基金将尽量选择可回售给发行方的证券公司短期公司债券进行投资;同时,紧急情况下,为保护基金份额持有人的利益,基金管理人还应当启用风险准备金防范流动性风险。4、债券回购投资策略在组合进行债券回购投资操作时,基金管理人将根究资金面走势等因素,选择回购的品种和期限。5、其他金融工具投资策略本基金将密切跟踪衍生产品等其他金融工具的动向。当监管机构允许基金参与其他金融工具的投资,本基金将按照届时生效的法律法规,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000389', '广发天天红A', '货币市场型基金', 164006915770.66, '2013-10-22', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将在深入研究国内外的宏观经济走势、货币政策变化趋势、市场资金供求状况的基础上,分析和判断利率走势与收益率曲线变化趋势,并综合考虑各类投资品种的收益性、流动性和风险特征,对基金资产组合进行积极管理。 (一)利率预期策略影响利率走势的因素很多,影响短期利率变动的因素更多,运行方式也更为复杂。基金管理人将重点考察以下两个因素: 1、中央银行、财政部等国家宏观经济管理部门的政策意图。政府对金融市场运行的影响非常深远。国家宏观经济管理部门尤其是中央银行对经济运行形势的判断及采取的应对政策是影响市场利率走势的关键因素之一。 2、短期资金供求变化。短期资金市场参与者的头寸宽紧程度是短期利率变动的重要主导力量。短期利率随短期资金供求变化呈一定的季节波动形态。具体而言,本基金管理人将持续跟踪反映国民经济变化的宏观经济指标,对国家经济政策进行深入分析,进而对短期利率的变化态势做出及时反应。重点关注的宏观经济指标包括:国家经济管理部门政策、预期物价指数、相关市场资金供求关系等等。在分析方法上,本基金管理人坚持定性与定量相结合的分析方法。 (二)期限配置策略在短期利率期限结构分析的基础上,根据对投资对象流动性和收益性的动态考察,构建合理期限结构的投资组合。从组合总的剩余期限结构来看,一般说来,预期利率上涨时,将适当缩短组合的平均期限;预期利率下降时,将在法律法规允许的范围内适当延长组合的平均剩余期限。 (三)品种配置策略在短期利率期限结构分析和品种深入分析的基础上,进行品种合理配置。当预期利率上涨时,可以增加回购资产的比重,适度降低债券资产的比重;预期利率下降,将降低回购资产的比重,增加债券资产的比重。 (四)银行定期存款及大额存单投资策略银行定期存款及大额存单是本基金的主要投资对象,因此,银行定期存款及大额存单的投资将是本基金关注的重点之一。具体而言,在组合投资过程中,本基金将在综合考虑成本收益的基础上,尽可能的扩大交易对手方的覆盖范围,通过对这些银行广泛、耐心而细致的询价,挖掘出利率报价较高的多家银行进行银行定期存款及大额存单的投资,在获取较高投资收益的同时尽量分散投资风险,提高存款及存单资产的流动性。 (五)套利策略在久期控制的基础上,本基金管理人将对货币市场的各个细分市场进行深入研究分析,在严格控制风险和保障流动性的前提下,寻找跨市场、跨期限、跨品种的套利投资机会,以期获得更高的收益。当然,由于交易机制的限制,目前挖掘套利投资机会的投资方法主要是用风险相当,但收益更高的品种替代收益较低的品种,或者用收益相当,风险较低的品种替代风险较高的品种。 (六)流动性管理策略流动性好是货币市场基金的重要特征之一。在日常的投资管理过程中,本基金将会紧密关注申购/赎回现金流变化情况、季节性资金流动等影响货币市场基金流动性管理的因素,建立组合流动性监控管理指标,实现对基金资产流动性的实时管理。具体而言,本基金将综合平衡基金资产在流动性资产和收益性资产之间的配置比例,通过现金留存、银行定期存款提前支取、持有高流动性券种、正向回购、降低组合久期等方式提高基金资产整体的流动性,也可采用持续滚动投资方法,将回购或债券的到期日进行均衡等量配置,以满足日常的基金资产变现需求。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('003536', '浦银日日丰D', '货币市场型基金', 161697705881.92, '2016-11-07', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将结合宏观分析和微观分析制定投资策略，力求在满足安全性、流动性需要的基础上实现更高的收益率。INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000621', '易方达现金增利B', '货币市场型基金', 154372746331.4, '2015-02-05', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金利用定性分析和定量分析方法,通过对短期金融工具的积极投资,在有效控制投资风险和保持高流动性的基础上,力争获得高于业绩比较基准的投资回报。1、资产配置策略基金管理人根据市场情况和可投资品种的容量,在严谨深入的研究分析基础上,综合考量市场资金面走向、存款银行的信用资质、信用债券的信用评级以及各类资产的收益率水平、流动性特征等,确定各类资产的配置比例。2、杠杆投资策略本基金将对回购利率与短期债券收益率、存款利率进行比较,并在对资金面进行综合分析的基础上,判断利差套利空间,并确定杠杆操作策略。3、银行存款及同业存单投资策略本基金在向交易对手银行进行询价的基础上,选取利率报价较高的银行进行存款投资,在投资过程中基于对交易对手信用风险的评估,选择交易对手。当银行存款投资具有较高投资价值时,本基金存款投资比例上限最高可达100%。4、债券回购投资策略本基金基于对资金面走势的判断,选择回购品种和期限。若资产配置中有逆回购,则在判断资金面趋于宽松的情况下,优先进行相对较长期限逆回购配置;反之,则进行相对较短期限逆回购操作。在组合进行杠杆操作时,根据资金面的松紧,决定正回购的操作期限。5、利率品种的投资策略本基金对国债、央行票据等利率品种的投资,是在对国内、国外经济趋势进行分析和预测基础上,运用数量方法,对利率期限结构变化趋势和债券市场供求关系变化进行分析和预测,深入分析利率品种的收益和风险,并据此调整债券组合的平均久期。在确定组合平均久期后,本基金对债券的期限结构进行分析,运用统计和数量分析技术,选择合适的期限结构配置策略,在合理控制风险的前提下,综合考虑组合的流动性,决定投资品种。6、信用品种的投资策略基金管理人通过“内部信用评级体系”对市场公开发行的短期融资券、中期票据、企业债、公司债和可分离转债存债等信用品种进行研究和筛选,形成信用债券投资备选库。在信用债券投资备选库基础上,结合本基金的投资与配置需要,通过分析比较到期收益率、剩余期限、流动性等特征,挑选适当的短期信用品种进行投资。对于证券公司短期公司债券,在基金管理人的“内部信用评级体系”中,对可选的证券公司短期公司债券品种进行筛选,综合考虑和分析发行主体的公司背景、竞争地位、治理结构、盈利能力、偿债能力、债券收益率等要素,确定投资决策。本基金将对拟投资或已投资的证券公司短期公司债券进行流动性分析和监测,并适当控制债券投资组合整体的久期,保证本基金的流动性。为防范大额赎回可能引发的流动性风险,本基金将尽量选择可回售给发行方的证券公司短期公司债券进行投资;同时,紧急情况下,为保护基金份额持有人的利益,基金管理人还应当启用风险准备金防范流动性风险。7、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向。当监管机构允许基金参与此类金融工具的投资,本基金将按照届时生效的法律法规,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('001211', '中欧滚钱宝A', '货币市场型基金', 153492893448.98, '2015-06-12', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金根据对短期利率变动的预测,采用投资组合平均剩余期限控制下的主动性投资策略,利用定性分析和定量分析方法,通过对短期金融工具的积极投资,在控制风险和保证流动性的基础上,力争获得稳定的当期收益。 1、利率预期与目标剩余期限管理策略 通过对宏观经济指标、资金市场供求状况等因素的跟踪分析,预测政府宏观经济政策取向和资金市场供求变化趋势,以此为依据预测金融市场利率变化趋势。 根据对宏观经济和短期资金市场的利率走势,来确定投资组合的平均剩余到期期限。具体而言,在预计市场利率上升时,适当缩短投资品种的平均期限;在预计利率下降时,适当延长投资品种的平均期限。 2、类属配置策略 在保持组合资产相对稳定的条件下,根据各类短期金融工具的市场规模、收益性和流动性,决定各类资产的配置比例;再通过评估各类资产的流动性和收益性利差,确定不同期限类别资产的具体资产配置比例。 3、个券选择策略在个券选择上,本基金通过定性定量方法,综合分析收益率曲线、流动性、信用风险,评估个券投资价值,发掘出具备相对价值的个券。 4、回购策略 1)息差放大策略:该策略是指利用回购利率低于债券收益率的机会通过循环回购以放大债券投资收益的投资策略。该策略的基本模式是利用买入债券进行正回购,再利用回购融入资金购买收益率较高债券品种,如此循环至回购期结束卖出债券偿还所融入资金。在进行回购放大操作时,基金管理人将严格遵守相关法律法规关于债券正回购的有关规定。 2)逆回购策略:基金管理人将密切关注由于新股申购等原因导致短期资金需求激增的机会,通过逆回购的方式融出资金以分享短期资金利率陡升的投资机会。 5、收益率曲线策略 本基金将根据债券市场收益率曲线以及隐含的即期收益率和远期利率提供的价值判断基础,结合对资金面的分析,匹配各期限的回购与债券品种的到期日,实现现金流的有效管理。 6、现金流管理策略 本基金作为现金管理工具,具有较高的流动性要求,本基金将根据对市场资金面分析以及对申购赎回变化的动态预测,通过回购的滚动操作和债券品种的期限结构搭配,动态调整并有效分配基金的现金流,在保持充分流动性的基础上争取较高收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('001821', '兴全天添益B', '货币市场型基金', 143165317087.75, '2015-11-05', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '根据宏观形势、利率走势等因素,确定各个阶段的投资组合平均久期、剩余期限等指标,并在这些指标要求的基础上构建投资组合;进行主动投资,有效提高资产组合收益。本基金综合运用类属配置、目标久期控制、收益曲线、个券选择、套利等多种投资策略进行投资: (1)类属配置策略 类属配置指组合在央行票据、债券回购、短期债券以及现金等投资品种之间的配置比例。本基金通过分析各类属的相对收益、利差变化、流动性风险、信用风险等因素来确定类属配置比例,寻找具有投资价值的投资品种,增持相对低估、价格将上升的,能给组合带来相对较高回报的类属;减持相对高估、价格将下降的,给组合带来相对较低回报的类属,借以取得较高的总回报。 (2)目标久期控制和流动性管理策略 本基金采用目标久期控制策略,根据对宏观环境中的市场、气氛和未来利率变动趋势的判断,深入分析收益率曲线与资金供求状况,确定并控制投资组合平均剩余期限,本基金的平均剩余期限控制在120天之内。如果预测利率将上升,可以适当降低组合的目标久期;如果预测利率将下降,则可以适当增加组合的目标久期。并通过控制同业存款的比例、保留充足的可变现资产和平均安排回购到期期限,保证组合的一定流动性。 (3)收益曲线策略 收益曲线策略即在不同期限投资品种之间进行的配置,通过考察收益率曲线的动态变化及预期变化,寻求在一段时期内获取因收益率曲线形状变化而导致的债券价格变化所产生的超额收益。在期限配置方面,将在久期决策的基础上,在不增加总体利率风险的情况下,集中于决定期限利差变化的因素,从不同期限的债券的相对价值变化中实现超额收益。 (4)个券选择策略 本基金认为普通债券,包括国债、金融债和企业债的估值,主要基于收益率曲线的拟合。在正确拟合收益率曲线的基础上,及时发现偏离市场收益率的债券,并帮助找出这些债券价格偏离的原因,同时,基于收益率曲线可以判断出定价偏高或偏低的期限段,从而指导相对价值投资,选择投资于定价低估的短期债券品种。 (5)套利策略 由于市场环境差异、交易市场分割、市场参与者差异,以及资金供求失衡导致的中短期利率异常差异,使得债券现券市场和回购市场上存在着套利机会。无风险套利主要包括银行间市场、交易所市场的跨市场套利和同一交易市场中不同品种的跨品种套利。 本基金在保证投资组合流动性的前提下,积极捕捉和把握无风险套利机会。寻找最佳时机,进行跨市场、跨品种操作,获得安全的超额收益。 (6)回购策略 本基金将根据对市场走势的判断,合理选择恰当的回购策略,以实现本基金资产的增值。通过回购可以进行放大,在市场上升的时候增加获取收益的能力,并利用买入——回购融资——再投资的机制放大资金使用效率,有机会博取更大的差价收益。在市场下跌时,则可使用买断式回购策略以规避风险。 (7)投资组合的优化配置 本基金将运用“兴全货币市场投资组合优化模型”对类属资产和整个投资组合进行优化配置,即在类属资产和整体投资组合久期控制的条件下追求最高的投资收益率。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000588', '招商招钱宝A', '货币市场型基金', 141747186120.23, '2014-03-25', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金以严谨的市场价值分析为基础,采用稳健的投资组合策略,通过对短期金融工具的组合操作,在保持本金的安全性与资产流动性的同时,追求稳定的当期收益。?根据宏观经济指标、货币政策的研究,确定组合平均剩余到期期限;?根据各期限各品种的流动性、收益性以及信用水平来确定组合资产配置;?根据市场资金供给情况对组合平均剩余期限以及投资品种比例进行适当调整;?在保证组合流动性的前提下,利用现代金融分析方法和工具,寻找价值被低估的投资品种和无风险套利机会。?合理有效分配基金的现金流,保持本基金的流动性。1、本基金主要投资策略的制定将依据以下投资方法和技术(1)短期资金市场同债券市场紧密相关,连接两个市场的分析工具是收益率曲线。本基金将根据债券市场收益率曲线以及隐含的短期收益率和远期利率提供的价值判断基础,为各种投资策略的制定提供决策依据。(2)短期资金市场的资金供给与需求研究短期利率是短期资金成本的反映。短期货币资金供应与需求决定了短期利率水平。短期资金市场资金供应量同以下几种因素相关:?央行公开市场操作的方向、强度、频率以及中标利率水平。短期利率是央行货币政策调控的主要目标之一,央行向短期资金市场注入资金或者从短期资金市场抽出资金,都对短期利率产生重大影响。?回购市场的交易量、成交的利率水平分布。?短期资金市场资金供给同资本市场资金供给的关系。一般在股市转暖、一级市场申购增多、新债交款日期附近资金面偏紧。?货币供应量的季节性因素。一般资金在年末时较为紧张,而在年初时则较为宽松。通过对这些不同因素的综合考虑,本基金可以概算市场资金供给的充裕程度,据此决定本基金的市场操作策略。(3)企业信用分析直接融资的发展是一个长期趋势,企业债、企业短期融资券因此也将成为货币市场基金重要的投资对象。为了保障基金资产的安全,本基金将按照相关法规仅投资于具有满足信用等级要求的企业债券、短期融资券。与此同时,本基金还将深入分析发行人的财务稳健性,判断发行人违约的可能性,严格控制企业债券、短期融资券的违约风险。(4)市场结构研究银行间市场与交易所市场在资金供给者和需求者结构上均存在差异,利率水平因此有所不同。不同类型市场工具由于存在税负、流动性、信用风险上的差异,其收益率水平也略有不同。资金供给者、需求者结构的变化也会引起利率水平的变化。积极利用这些利率差异、利率变化就可能在保证流动性、安全性的基础上为基金资产带来更高的收益率。2、本基金具体操作策略(1)滚动配置策略本基金将根据具体投资品种的市场特性采用持续投资的方法,既能提高基金资产变现能力的稳定性,又能保证基金资产收益率与市场利率的基本一致。(2)久期控制策略本基金将根据对货币市场利率趋势的判断来配置基金资产的久期。在预期利率上升时,缩短基金资产的久期,以规避资本损失或获得较高的再投资收益;在预期利率下降时,延长基金资产的久期,以获取资本利得或锁定较高的收益率。(3)套利策略套利策略包括跨市场套利和跨品种套利。跨市场套利是利用同一金融工具在各个子市场的不同表现进行套利。跨品种套利是利用不同金融工具的收益率差别,在满足基金自身流动性、安全性需要的基础上寻求更高的收益率。(4)时机选择策略股票、债券发行以及年末效应等因素可能会使市场资金供求情况发生暂时失衡,从而推高市场利率。充分利用这种失衡就能提高基金资产的收益率。A.根据宏观经济和短期资金市场的利率走势,来确定投资组合的平均剩余到期期限。具体而言,在预计市场利率上升时,适当缩短投资品种的平均期限;在预计利率下降时,适当延长投资品种的平均期限。市场对利率的预期可以从市场的交易变化和资金流向上反映出来,也可通过不同品种之间反映出的隐含远期利率来评估市场未来利率的走势。B.根据自有的资产配置模型,结合各品种之间的流动性、收益性以及信用风险情况,来确定组合的资产配置比例。其前提条件是保证基金的高流动性、低风险和稳定收益。C.根据当期和远期市场资金面充裕程度的分析,匹配各期限的回购与债券品种的到期日,实现现金流的有效管理。D.目前短期资金市场分为银行间市场和交易所市场两个子市场,其中投资群体、交易方式等市场要素不同,使得两个市场的资金面和市场短期利率在一定期间内可能存在定价偏离。本基金在充分论证这种套利机会可行性的基础上,寻找最佳介入时机,进行跨市场操作,获得安全的超额收益。E.由于投资群体的差异,对期限相近的品种,因为其流动性、税收等因素造成内在价值出现明显偏离时,本基金可以在保证流动性的基础上,进行品种间的套利操作,增加超额收益。F.积极参与国债、金融债、央行票据一级市场投标,增加盈利空间。一级市场发行的国债、金融债数量大且连续,提供了有效的品种建仓机会。本基金管理人根据二级市场的收益水平和市场资金面的状况,对一级市场进行准确的招标预测,决定本基金的投标价位。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('004137', '博时合惠B', '货币市场型基金', 140454075468.71, '2017-01-13', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采用积极管理型的投资策略，在控制利率风险、尽量降低基金资产净值波动风险并满足流动性的前提下，提高基金收益。INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('003515', '国泰利是宝', '货币市场型基金', 138540448289.78, '2016-12-22', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将结合宏观分析和微观分析制定投资策略，力求在满足安全性、流动性需要的基础上实现更高的收益率。INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000699', '中银薪钱包', '货币市场型基金', 137808988623.58, '2014-06-26', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金通过综合考虑各类资产的收益性、流动性和风险特征,根据定量和定性方法,在保持投资组合较低风险和良好流动性的基础上,力争获得高于业绩比较基准的稳定投资回报。 1、资产配置策略本基金将根据市场情况和可投资品种的容量,在严谨深入的研究分析基础上,综合考量市场资金面走向、存款银行的信用资质以及各类资产的收益率水平、流动性特征等,确定各类资产的配置比例。 2、久期控制策略本基金根据对宏观经济和短期资金市场的利率走势,确定投资组合的平均剩余到期期限。具体而言,在预计市场利率上升时,适当缩短投资品种的平均期限以规避资本损失或获得较高的再投资收益;在预计利率下降时,适当延长投资品种的平均期限,以获取资本利得或锁定较高的收益。 3、银行定期存款及大额存单投资策略本基金在向交易对手银行进行询价的基础上,选取利率报价较高的银行进行存款投资,在投资过程中注重对交易对手信用风险的评估和选择,在严格控制风险的前提下决定各银行存款及大额存单的投资比例。 4、短期信用类债券投资策略本基金通过建立“内部信用评级体系”对市场公开发行的所有短期融资券、中期票据、企业债、公司债、可分离转债存债等信用品种进行研究和筛选,形成信用债券投资备选库。结合本基金的投资与配置需要,通过对到期收益率、剩余期限、流动性特征等进行分析比较,挑选适当的短期信用品种进行投资。 5、债券回购投资策略本基金基于对资金面走势的判断,选择回购品种和期限。当回购利率低于债券收益率时,采用息差放大策略,该策略的基本模式是利用已买入债券进行正回购,再利用回购融入资金购买收益率较高债券品种,如此循环至回购期结束卖出债券偿还所融入资金。在进行回购放大操作时,基金管理人将严格遵守相关法律法规关于债券正回购的有关规定。当回购利率高于债券收益率时,本基金将通过逆回购的方式融出资金以分享短期资金利率陡升的投资机会。 6、资产支持证券投资策略本基金管理人通过考量宏观经济形势、提前偿还率、违约率、资产池结构以及资产池资产所在行业景气情况等因素,预判资产池未来现金流变动;研究标的证券发行条款,预测提前偿还率变化对标的证券平均久期及收益率曲线的影响,同时密切关注流动性变化对标的证券收益率的影响,在严格控制信用风险暴露程度的前提下,通过信用研究和流动性管理,选择风险调整后收益较高的品种进行投资。 7、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向,一旦监管机构允许基金参与此类金融工具的投资,本基金将在届时相应法律法规的框架内,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('003042', '交银活期通A', '货币市场型基金', 130442838403.97, '2016-07-27', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金在保持组合高度流动性的前提下，结合对国内外宏观经济运行、金融市场运行、资金流动格局、货币市场收益率曲线形态等各方面的分析，合理安排组合期限结构，积极选择投资工具，采取主动性的投资策略和精细化的操作手法。具体包括：INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000848', '工银添益快线A', '货币市场型基金', 129415451182.1, '2014-10-22', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采取利率策略、信用策略、相对价值策略等积极投资策略,在严格控制风险的前提下,发掘和利用市场失衡提供的投资机会,实现组合增值。 1、利率策略通过全面研究GDP、物价、就业以及国际收支等主要经济变量,分析宏观经济运行的可能情景,并预测财政政策、货币政策等宏观经济政策取向,分析金融市场资金供求状况变化趋势及结构。在此基础上,预测金融市场利率水平变动趋势,以及金融市场收益率曲线斜度变化趋势。 2、信用策略根据国民经济运行周期阶段,分析债券发行人所处行业发展前景、发展状况、市场地位、财务状况、管理水平和债务水平等因素,评价债券发行人的信用风险。跟踪债券发行人和债券工具自身的信用质量变化,并结合外部权威评级机构的信用评级结果,确定基金资产对相应债券的投资决策。 3、类属配置策略研究国民经济运行状况,货币市场及资本市场资金供求关系,以及不同时期市场投资热点,分析国债、金融债、企业债券等不同债券种类的利差水平,评定不同债券类属的相对投资价值,确定组合资产在不同债券类属之间配置比例。 4、个券选择策略本基金认为普通债券的估值,主要基于收益率曲线的拟合。在正确拟合收益率曲线的基础上,及时发现偏离市场收益率的债券,并找出因投资者偏好、供求、流动性、信用利差等导致债券价格偏离的原因;同时,基于收益率曲线判断出定价偏高或偏低的期限段,从而指导相对价值投资,选择出估值较低的债券品种。对于含回售条款的债券,本基金将仅买入距回售日不超过397天以内的债券,并在回售日前进行回售或者卖出。 5、相对价值策略本基金认为市场普遍存在着失效的现象,短期因素的影响被过分夸大。债券市场的参与者众多,投资行为、风险偏好、财务与税收处理等各不相同,发掘存在于这些不同因素之间的相对价值,也是本基金发现投资机会的重要方面。本基金密切关注国家法律法规、制度的变动,通过深入分析市场参与者的立场和观点,充分利用因市场分割、市场投资者不同风险偏好或者税收待遇等因素导致的市场失衡机会,形成相对价值投资策略,运用回购、远期交易合同等交易工具进行不同期限、不同品种或不同市场之间的套利交易,为本基金的投资带来增加价值。 6、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向。当法律法规允许基金参与此类金融工具的投资,本基金将按照届时生效的法律法规,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000380', '景顺长城景益货币A', '货币市场型基金', 125664111912.27, '2013-11-26', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1.整体资产配置策略本基金根据对短期利率变动的合理预判,采用投资组合平均剩余期限控制下的主动性投资策略,利用定性分析和定量分析方法,综合分析宏观经济指标,包括全球经济发展形势、国内经济情况、货币政策、财政政策、物价水平变动趋势、利率水平和市场预期、通货膨胀率、货币供应量等,对短期利率走势进行综合判断,同时分析央行公开市场操作、主流资金的短期投资倾向、债券供给、货币市场与资本市场资金互动等,并根据动态预期决定和调整组合的平均剩余期限。预期市场利率水平上升,适度缩短投资组合的平均剩余期限,以降低组合下跌风险;预期市场利率水平下降,适度延长投资组合的平均剩余期限,以分享债券价格上升的收益。 2.类属配置策略 类属配置是指基金组合在国债、央行票据、债券回购、金融债、短期融资券及现金等投资品种之间的配置比例。实现基金流动性需求并获得投资收益。 通过对各类别金融工具政策倾向、税收政策、信用等级、收益率水平、资金供求、流动性等因素的研究判断,来确定并动态调整投资组合国债、央行票据、债券回购、金融债、短期融资券及现金等各类属品种的配置比例,以满足投资人对基金流动性的需求,并达到获取投资收益的目的 3.个券选择策略 在个券选择层面,将首先考虑安全性因素,优先选择央票、短期国债等高信用等级的债券品种以规避违约风险。除考虑安全性因素外,在具体的券种选择上,基金管理人将在正确拟合收益率曲线的基础上,找出收益率明显偏高的券种,并客观分析收益率出现偏离的原因。若出现因市场原因所导致的收益率高于公允水平,则该券种价格出现低估,本基金将对此类低估值品种进行重点关注。此外,鉴于收益率曲线可以判断出定价偏高或偏低的期限段,从而指导相对价值投资,这也可以帮助基金管理人选择投资于定价低估的短期债券品种。 4.套利策略 由于市场环境差异、交易市场分割、市场参与者差异、资金供求失衡、流动性等因素造成不同交易市场或不同交易品种出现定价差异现象,从而使债券市场上存在套利机会。在保证安全性和流动性的前提下,本基金将在充分验证这种套利机会可行性的基础上,适当参与市场的套利,捕捉和把握无风险套利机会,以获取安全的超额收益。 5.回购策略 (1)息差放大策略:该策略是指利用回购利率低于债券收益率的机会通过循环回购以放大债券投资收益的投资策略。该策略的基本模式是利用买入债券进行正回购,再利用回购融入资金购买收益率较高债券品种,如此循环至回购期结束卖出债券偿还所融入资金。在进行回购放大操作时,基金管理人将严格遵守相关法律法规关于债券正回购的有关规定。 (2)逆回购策略:基金管理人将密切关注由于新股申购等原因导致短期资金需求激增的机会,通过逆回购的方式融出资金以分享短期资金利率陡升的投资机会。 6.流动性管理策略 本基金将保持高流动性的特性,将建立流动性预警指标,动态调整基金资产在流动性资产和收益性资产之间的配置比例。同时,密切关注本基金申购/赎回、季节性资金流动等情况,日历效应等,适时通过现金留存、提高流动性券种比例等方式提高基金资产整体的流动性,以确保基金资产的整体变现能力。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('005065', '中金现金管家C', '货币市场型基金', 123618420938.01, '2017-09-04', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1、短期利率预期策略根据对宏观经济指标、货币政策、市场结构变化和市场资金供求等因素的研究与分析,对未来一段时期的短期市场利率进行积极的判断,对短期利率走势形成合理预期,并据此调整基金资产的配置策略。 2、类属配置策略在保持基金资产相对稳定的前提下,通过对市场资金供求、基金申赎情况进行动态分析,确定本基金流动性目标,相应调整基金资产在高流动性资产和相对流动性较低资产之间的配比。结合各类资产的收益率水平、流动性特征、信用风险等因素来确定并动态调整基金资产中央行票据、国债、债券回购等各类属品种的配置比例。 3、期限配置策略根据对短期利率走势的判断确定并调整组合的平均剩余期限。在预期利率上升时,缩短组合的平均剩余期限,以规避资本损失或获得较高的再投资收益;在预期利率下降时,延长组合的平均剩余期限,以获得资本利得或锁定较高的利率水平。 4、跨市场和品种套利策略短期资金市场分为银行间市场和交易所市场两个子市场,投资群体、交易方式等市场要素的不同使得两个市场的资金面和市场短期利率在一定期间内可能存在定价偏离。在充分论证上述套利机会可行性的基础上,寻找最佳介入时机,进行跨市场操作,获得安全的超额收益。对期限相近的品种,由于流动性、税收等因素造成内在价值出现明显偏离时,可以在保证流动性的基础上,进行品种间的套利操作,增加超额收益。 5、流动性管理策略作为现金管理工具,本基金必须保持较高的流动性。在遵循流动性优先的原则下,本基金将建立流动性预警指标,动态调整基金资产在流动性资产和收益性资产之间的配置比例。同时,密切关注申购、赎回、季节性资金流动等情况,在保持基金资产高流动性的前提下,通过现金库存、资产变现、剩余期限管理等措施确保基金资产的整体变现能力。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000677', '工银现金快线A', '货币市场型基金', 122729677217.73, '2014-09-23', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采取利率策略、信用策略、相对价值策略等积极投资策略,在严格控制风险的前提下,发掘和利用市场失衡提供的投资机会,实现组合增值。 1、利率策略通过全面研究GDP、物价、就业以及国际收支等主要经济变量,分析宏观经济运行的可能情景,并预测财政政策、货币政策等宏观经济政策取向,分析金融市场资金供求状况变化趋势及结构。在此基础上,预测金融市场利率水平变动趋势,以及金融市场收益率曲线斜度变化趋势。 2、信用策略根据国民经济运行周期阶段,分析债券发行人所处行业发展前景、发展状况、市场地位、财务状况、管理水平和债务水平等因素,评价债券发行人的信用风险。跟踪债券发行人和债券工具自身的信用质量变化,并结合外部权威评级机构的信用评级结果,确定基金资产对相应债券的投资决策。 3、类属配置策略研究国民经济运行状况,货币市场及资本市场资金供求关系,以及不同时期市场投资热点,分析国债、金融债、企业债券等不同债券种类的利差水平,评定不同债券类属的相对投资价值,确定组合资产在不同债券类属之间配置比例。 4、个券选择策略本基金认为普通债券的估值,主要基于收益率曲线的拟合。在正确拟合收益率曲线的基础上,及时发现偏离市场收益率的债券,并找出因投资者偏好、供求、流动性、信用利差等导致债券价格偏离的原因;同时,基于收益率曲线判断出定价偏高或偏低的期限段,从而指导相对价值投资,选择出估值较低的债券品种。 对于含回售条款的债券,本基金将仅买入距回售日不超过397天以内的债券,并在回售日前进行回售或者卖出。 5、相对价值策略本基金认为市场普遍存在着失效的现象,短期因素的影响被过分夸大。债券市场的参与者众多,投资行为、风险偏好、财务与税收处理等各不相同,发掘存在于这些不同因素之间的相对价值,也是本基金发现投资机会的重要方面。本基金密切关注国家法律法规、制度的变动,通过深入分析市场参与者的立场和观点,充分利用因市场分割、市场投资者不同风险偏好或者税收待遇等因素导致的市场失衡机会,形成相对价值投资策略,运用回购、远期交易合同等交易工具进行不同期限、不同品种或不同市场之间的套利交易,为本基金的投资带来增加价值。 6、资产支持证券投资策略当前国内资产支持证券主要为以银行贷款资产、住房抵押贷款等作为基础资产的信贷资产证券化产品,本基金侧重于对基础资产质量及未来现金流的分析,采用基本面分析和数量化模型相结合,对个券进行风险分析和价值评估后进行投资。本基金将严格控制资产支持证券的投资比例、信用等级并密切跟踪评级变化,采用分散投资方式以降低流动性风险。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('003281', '广发活期宝B', '货币市场型基金', 122698898791.17, '2016-09-02', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将在深入研究国内外的宏观经济走势、货币政策变化趋势、市场资金供求状况的基础上,分析和判断利率走势与收益率曲线变化趋势,并综合考虑各类投资品种的收益性、流动性和风险特征,对基金资产组合进行积极管理。 (一)利率预期策略影响利率走势的因素很多,影响短期利率变动的因素更多,运行方式也更为复杂。基金管理人将重点考察以下两个因素: 1、中央银行、财政部等国家宏观经济管理部门的政策意图。政府对金融市场运行的影响非常深远。国家宏观经济管理部门尤其是中央银行对经济运行形势的判断及采取的应对政策是影响市场利率走势的关键因素之一。 2、短期资金供求变化。短期资金市场参与者的头寸宽紧程度是短期利率变动的重要主导力量。短期利率随短期资金供求变化呈一定的季节波动形态。具体而言,本基金管理人将持续跟踪反映国民经济变化的宏观经济指标,对国家经济政策进行深入分析,进而对短期利率的变化态势做出及时反应。重点关注的宏观经济指标包括:国家经济管理部门政策、预期物价指数、相关市场资金供求关系等等。在分析方法上,本基金管理人坚持定性与定量相结合的分析方法。 (二)期限配置策略在短期利率期限结构分析的基础上,根据对投资对象流动性和收益性的动态考察,构建合理期限结构的投资组合。从组合总的剩余期限结构来看,一般说来,预期利率上涨时,将适当缩短组合的平均期限;预期利率下降时,将在法律法规允许的范围内适当延长组合的平均剩余期限。 (三)品种配置策略在短期利率期限结构分析和品种深入分析的基础上,进行品种合理配置。当预期利率上涨时,可以增加回购资产的比重,适度降低债券资产的比重;预期利率下降,将降低回购资产的比重,增加债券资产的比重。 (四)银行定期存款及大额存单投资策略银行定期存款及大额存单是本基金的主要投资对象,因此,银行定期存款及大额存单的投资将是本基金关注的重点之一。具体而言,在组合投资过程中,本基金将在综合考虑成本收益的基础上,尽可能的扩大交易对手方的覆盖范围,通过对这些银行广泛、耐心而细致的询价,挖掘出利率报价较高的多家银行进行银行定期存款及大额存单的投资,在获取较高投资收益的同时尽量分散投资风险,提高存款及存单资产的流动性。 (五)套利策略在久期控制的基础上,本基金管理人将对货币市场的各个细分市场进行深入研究分析,在严格控制风险和保障流动性的前提下,寻找跨市场、跨期限、跨品种的套利投资机会,以期获得更高的收益。当然,由于交易机制的限制,目前挖掘套利投资机会的投资方法主要是用风险相当,但收益更高的品种替代收益较低的品种,或者用收益相当,风险较低的品种替代风险较高的品种。 (六)流动性管理策略流动性好是货币市场基金的重要特征之一。在日常的投资管理过程中,本基金将会紧密关注申购/赎回现金流变化情况、季节性资金流动等影响货币市场基金流动性管理的因素,建立组合流动性监控管理指标,实现对基金资产流动性的实时管理。具体而言,本基金将综合平衡基金资产在流动性资产和收益性资产之间的配置比例,通过现金留存、银行定期存款提前支取、持有高流动性券种、正向回购、降低组合久期等方式提高基金资产整体的流动性,也可采用持续滚动投资方法,将回购或债券的到期日进行均衡等量配置,以满足日常的基金资产变现需求。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('004501', '嘉实现金添利', '货币市场型基金', 122531391104.81, '2017-03-29', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1、资产配置策略INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000645', '华夏薪金宝', '货币市场型基金', 118913503873.3, '2014-05-26', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1、资产配置策略基金根据宏观经济运行状况、政策形势、信用状况、利率走势、资金供求变化等的综合判断,并结合各类资产的流动性特征、风险收益、估值水平特征,决定基金资产在债券、银行存款等各类资产的配置比例,并适时进行动态调整。 2、个券选择策略在个券选择上,基金将综合运用收益率曲线分析、流动性分析、信用风险分析等方法来评估个券的投资价值,发掘出具备相对价值的个券。 3、银行存款投资策略基金根据不同银行的银行存款收益率情况,结合银行的信用等级、存款期限等因素的分析,以及对整体利率市场环境及其变动趋势的研究,在严格控制风险的前提下选择具有较高投资价值的银行存款进行投资。 4、利用短期市场机会的灵活策略由于市场分割、信息不对称、发行人信用等级意外变化等情况会造成短期内市场失衡;新股、新债发行以及年末效应等因素会使市场资金供求发生短时的失衡。这种失衡将带来一定市场机会。通过分析短期市场机会发生的动因,研究其中的规律,据此调整组合配置,改进操作方法,积极利用市场机会获得超额收益。未来,随着证券市场投资工具的发展和丰富,本基金可相应调整和更新相关投资策略,并在招募说明书更新中公告。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('003474', '南方天天利B', '货币市场型基金', 115400683008.95, '2016-10-20', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采用积极管理型的投资策略，在控制利率风险、尽量降低基金净值波动风险并满足流动性的前提下，提高基金收益。INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('001134', '广发天天利E', '货币市场型基金', 115083271360.05, '2015-03-23', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将在深入研究国内外的宏观经济走势、货币政策变化趋势、市场资金供求状况的基础上,分析和判断利率走势与收益率曲线变化趋势,并综合考虑各类投资品种的收益性、流动性和风险特征,对基金资产组合进行积极管理。 (一)利率预期策略影响利率走势的因素很多,影响短期利率变动的因素更多,运行方式也更为复杂。基金管理人将重点考察以下两个因素: 1、中央银行、财政部等国家宏观经济管理部门的政策意图。政府对金融市场运行的影响非常深远。国家宏观经济管理部门尤其是中央银行对经济运行形势的判断及采取的应对政策是影响市场利率走势的关键因素之一。 2、短期资金供求变化。短期资金市场参与者的头寸宽紧程度是短期利率变动的重要主导力量。短期利率随短期资金供求变化呈一定的季节波动形态。具体而言,本基金管理人将持续跟踪反映国民经济变化的宏观经济指标,对国家经济政策进行深入分析,进而对短期利率的变化态势做出及时反应。重点关注的宏观经济指标包括:国家经济管理部门政策、预期物价指数、相关市场资金供求关系等等。在分析方法上,本基金管理人坚持定性与定量相结合的分析方法。 (二)期限配置策略在短期利率期限结构分析的基础上,根据对投资对象流动性和收益性的动态考察,构建合理期限结构的投资组合。从组合总的剩余期限结构来看,一般说来,预期利率上涨时,将适当缩短组合的平均期限;预期利率下降时,将在法律法规允许的范围内适当延长组合的平均剩余期限。 (三)品种配置策略在短期利率期限结构分析和品种深入分析的基础上,进行品种合理配置。当预期利率上涨时,可以增加回购资产的比重,适度降低债券资产的比重;预期利率下降,将降低回购资产的比重,增加债券资产的比重。 (四)银行定期存款及大额存单投资策略银行定期存款及大额存单是本基金的主要投资对象,因此,银行定期存款及大额存单的投资将是本基金关注的重点之一。具体而言,在组合投资过程中,本基金将在综合考虑成本收益的基础上,尽可能的扩大交易对手方的覆盖范围,通过对这些银行广泛、耐心而细致的询价,挖掘出利率报价较高的多家银行进行银行定期存款及大额存单的投资,在获取较高投资收益的同时尽量分散投资风险,提高存款及存单资产的流动性。 (五)套利策略在久期控制的基础上,本基金管理人将对货币市场的各个细分市场进行深入研究分析,在严格控制风险和保障流动性的前提下,寻找跨市场、跨期限、跨品种的套利投资机会,以期获得更高的收益。当然,由于交易机制的限制,目前挖掘套利投资机会的投资方法主要是用风险相当,但收益更高的品种替代收益较低的品种,或者用收益相当,风险较低的品种替代风险较高的品种。 (六)流动性管理策略流动性好是货币市场基金的重要特征之一。在日常的投资管理过程中,本基金将会紧密关注申购/赎回现金流变化情况、季节性资金流动等影响货币市场基金流动性管理的因素,建立组合流动性监控管理指标,实现对基金资产流动性的实时管理。具体而言,本基金将综合平衡基金资产在流动性资产和收益性资产之间的配置比例,通过现金留存、银行定期存款提前支取、持有高流动性券种、正向回购、降低组合久期等方式提高基金资产整体的流动性,也可采用持续滚动投资方法,将回购或债券的到期日进行均衡等量配置,以满足日常的基金资产变现需求。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('010727', '建信现金增利货币B', '货币市场型基金', 114676632332.03, '2020-11-17', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采取个券选择策略、利率策略等积极投资策略，在严格控制风险的前提下，发掘和利用市场失衡提供的投资机会，实现组合增值。INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000509', '广发钱袋子A', '货币市场型基金', 109625863057.51, '2014-01-10', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将在深入研究国内外的宏观经济运行情况、政策形势、信用状态、货币政策变化趋势、市场资金供求状况的基础上,分析和判断利率走势与收益率曲线变化趋势,并综合考虑各类投资品种的流动性特征、风险特征和估值水平特征,决定基金资产在银行存款、债券等各类资产的配置比例,并适时进行动态调整。 (一)利率预期策略影响利率走势的因素很多,影响短期利率变动的因素更多,运行方式也更为复杂。基金管理人将重点考察以下两个因素: 1、中央银行、财政部等国家宏观经济管理部门的政策意图。政府对金融市场运行的影响非常深远。国家宏观经济管理部门尤其是中央银行对经济运行形势的判断及采取的应对政策是影响市场利率走势的关键因素之一。 2、短期资金供求变化。短期资金市场参与者的头寸宽紧程度是短期利率变动的重要主导力量。短期利率随短期资金供求变化呈一定的季节波动形态。具体而言,本基金管理人将持续跟踪反映国民经济变化的宏观经济指标,对国家经济政策进行深入分析,进而对短期利率的变化态势做出及时反应。重点关注的宏观经济指标包括:国家经济管理部门政策、预期物价指数、相关市场资金供求关系等等。在分析方法上,本基金管理人坚持定性与定量相结合的分析方法。 (二)期限配置策略在短期利率期限结构分析的基础上,根据对投资对象流动性和收益性的动态考察,构建合理期限结构的投资组合。从组合总的剩余期限结构来看,一般说来,预期利率上涨时,将适当缩短组合的平均期限;预期利率下降时,将在法律法规允许的范围内适当延长组合的平均剩余期限。 (三)品种配置策略在短期利率期限结构分析和品种深入分析的基础上,进行品种合理配置。当预期利率上涨时,可以增加回购资产的比重,适度降低债券资产的比重;预期利率下降,将降低回购资产的比重,增加债券资产的比重。 (四)银行定期存款及大额存单投资策略银行定期存款及大额存单是本基金的主要投资对象之一,因此,银行定期存款及大额存单的投资将是本基金关注的重点之一。具体而言,在组合投资过程中,本基金将在综合考虑成本收益的基础上,尽可能的扩大交易对手方的覆盖范围,通过对这些银行广泛、耐心而细致的询价,挖掘出利率报价较高的多家银行进行银行定期存款及大额存单的投资,在获取较高投资收益的同时尽量分散投资风险,提高存款及存单资产的流动性。 (五)套利策略在久期控制的基础上,本基金管理人将对货币市场的各个细分市场进行深入研究分析,在严格控制风险和保障流动性的前提下,寻找跨市场、跨期限、跨品种的套利投资机会,以期获得更高的收益。当然,由于交易机制的限制,目前挖掘套利投资机会的投资方法主要是用风险相当,但收益更高的品种替代收益较低的品种,或者用收益相当,风险较低的品种替代风险较高的品种。 (六)流动性管理策略流动性好是货币市场基金的重要特征之一。在日常的投资管理过程中,本基金将会紧密关注申购/赎回现金流变化情况、季节性资金流动等影响货币市场基金流动性管理的因素,建立组合流动性监控管理指标,实现对基金资产流动性的实时管理。具体而言,本基金将综合平衡基金资产在流动性资产和收益性资产之间的配置比例,通过现金留存、银行定期存款提前支取、持有高流动性券种、正向回购、降低组合久期等方式提高基金资产整体的流动性,也可采用持续滚动投资方法,将回购或债券的到期日进行均衡等量配置,以满足日常的基金资产变现需求。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000330', '汇添富现金宝A', '货币市场型基金', 100832712760.8, '2013-09-12', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将结合宏观分析和微观分析制定投资策略,力求在满足安全性、流动性需要的基础上实现更高的收益率。1、本基金的投资策略将基于以下研究分析:(1)市场利率研究A、宏观经济趋势宏观经济状况是央行制定货币政策的基础,也是影响经济总体货币需求的关键因素,因此宏观经济趋势基本上确定了未来较长时期内的利率水平。在分析宏观经济趋势时,本基金重点关注两个因素。一是经济增长前景;二是通货膨胀率及其预期。B、央行的货币政策取向包括基准存、贷款利率,法定存款准备金率,公开市场操作的方向、力度,以及央行的窗口指导等。央行的货币政策取向是影响货币市场利率的最直接因素。在央行紧缩货币、提高基准利率时,市场利率一般会相应上升;而央行放松货币、降低基准利率时,市场利率则相应下降。C、商业银行的信贷扩张商业银行的信贷扩张是央行实现其货币政策目标的重要途径,也是经济总体货币需求的体现。因此商业银行的信贷扩张对货币市场利率具有举足轻重的影响。一般来说,商业银行信贷扩张越快,表明经济总体的货币需求越旺盛,货币市场利率也越高;反之,信贷扩张越慢,货币市场利率也越低。D、国际资本流动中国日益成为一个开放的国家,国际资本进出也更加频繁,并导致央行被动的投放或收回基础货币,造成货币市场利率的波动。在人民币汇率制度已经从钉住美元转为以市场供求为基础、参考一篮子货币进行调节、有管理的浮动汇率制度的情况下,国际资本流动对国内市场利率的影响也越发重要。E、其他影响短期资金供求关系的因素包括财政存款的短期变化,市场季节性、突发性的资金需求等。(2)市场结构研究银行间市场与交易所市场在资金供给者和需求者结构上均存在差异,利率水平因此有所不同。不同类型市场工具由于存在税负、流动性、信用风险上的差异,其收益率水平也略有不同。资金供给者、需求者结构的变化也会引起利率水平的变化。积极利用这些利率差异、利率变化就可能在保证流动性、安全性的基础上为基金资产带来更高的收益率。(3)企业信用分析直接融资的发展是一个长期趋势,企业债、企业短期融资券因此也将成为货币市场基金重要的投资对象。为了保障基金资产的安全,本基金将按照相关法规仅投资于具有满足信用等级要求的企业债券、短期融资券。与此同时,本基金还将深入分析发行人的财务稳健性,判断发行人违约的可能性,严格控制企业债券、短期融资券的违约风险。2、本基金具体投资策略(1)滚动配置策略本基金将根据具体投资品种的市场特性采用持续投资的方法,既能提高基金资产变现能力的稳定性,又能保证基金资产收益率与市场利率的基本一致。(2)久期控制策略本基金将根据对货币市场利率趋势的判断来配置基金资产的久期。在预期利率上升时,缩短基金资产的久期,以规避资本损失或获得较高的再投资收益;在预期利率下降时,延长基金资产的久期,以获取资本利得或锁定较高的收益率。(3)套利策略套利策略包括跨市场套利和跨品种套利。跨市场套利是利用同一金融工具在各个子市场的不同表现进行套利。跨品种套利是利用不同金融工具的收益率差别,在满足基金自身流动性、安全性需要的基础上寻求更高的收益率。(4)时机选择策略股票、债券发行以及年末效应等因素可能会使市场资金供求情况发生暂时失衡,从而推高市场利率。充分利用这种失衡就能提高基金资产的收益率。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('001624', '兴业添天盈A', '货币市场型基金', 100647875103.26, '2015-07-23', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金根据对短期利率变动的预测,采用投资组合平均剩余期限控制下的主动性投资策略,利用定性分析和定量方法,在控制风险和保证流动性的基础上,力争获得稳定当期收益。 1、资产配置策略本基金通过对宏观经济形势、财政与货币政策、金融监管政策、市场结构变化和短期资金供给等因素的分析,形成对未来短期利率走势的判断。在此基础上,根据不同类别资产的收益率水平(各剩余期限、利息支付方式和再投资便利性),并结合各类资产的流动特征(日均成交量、交易方式和市场流量)和风险特征(信用等级、波动性),决定各类资产的配置比例和期限匹配量。 2、个券选择策略本基金将优先考虑安全性因素,选择央行票据、短期国债和短期融资票据等高信用等级的券品种进行投资以规避风险。在基金的个券选择上,本基金首先将各种券种信用等级、剩余期限和流动性进行初步筛选;然后,根据各券种的收益率与剩余期限结构合理性评估其投资价值进行再次筛选;最后,根据各券种的到期收益率波动性与可投资量(流通、日均成交量与冲击成本估算),决定具体投资比例。 3、久期策略本基金根据对未来短期利率走势的预判,结合货币市场基金资产的高流动性要求及其相关的投资比例规定,动态调整组合的久期。当预期市场短期利率上升时,本基金将通过增加持有剩余期限较短债券并减持剩余期限较长债券等方式降低组合久期,以降低组合跌价风险;当预期市场短期利率下降时,则通过增持剩余期限较长的债券等方式提高组合久期,以分享债券价格上升的收益。 4、回购策略根据回购市场利率走势变化情况,在较低时本基金严格遵守相关法律法规的前提下,利用正回购操作循环融入资金进行债券投资,以提高基金收益水平。另一方面,本基金将把握资金供求的瞬时效应,积极捕捉收益率峰值短线机会。如新股发行期间、年末资金回笼时的季节效应等短供求失衡,导致回购利率突增等。此时,本基金可通过逆回购的方式融出资金以分享短期拆借利率陡升的投资机会。 5、现金流管理策略本基金作为现金管理工具,具有较高的流动性要求,本基金将根据对市场资金面分析以及对申购赎回变化的动态预测,通过回购的滚动操作和债券品种的期限结构搭配,动态调整并有效分配基金的现金流,在保持充分流动性的基础上争取较高收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000710', '交银现金宝A', '货币市场型基金', 100062278706.14, '2014-09-12', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金在保持组合高度流动性的前提下,结合对国内外宏观经济运行、金融市场运行、资金流动格局、货币市场收益率曲线形态等各方面的分析,合理安排组合期限结构,积极选择投资工具,采取主动性的投资策略和精细化的操作手法。具体包括: 1、短期利率水平预期策略深入分析国家货币政策、短期资金市场利率波动、资本市场资金面的情况和流动性的变化,对短期利率走势形成合理预期,并据此调整基金货币资产的配置策略。 2、收益率曲线分析策略根据收益率曲线的变化趋势,采取相应的投资管理策略。货币市场收益率曲线的形状反映当时短期利率水平之间的关系,反映市场对较短期限经济状况的判断及对未来短期经济走势的预期。 3、组合剩余期限策略、期限配置策略通过对组合资产剩余期限的设计、跟踪、调整,达到保持合理的现金流,锁定组合剩余期限,以满足可能的、突发的现金需求,同时保持组合的稳定收益;特别在债券投资中,根据收益率曲线的情况,投资一定剩余期限的品种,稳定收益,锁定风险,满足组合目标期限。 4、类别品种配置策略在保持组合资产相对稳定的条件下,根据各类短期金融工具的市场规模、收益性和流动性,决定各类资产的配置比例;再通过评估各类资产的流动性和收益性利差,确定不同期限类别资产的具体资产配置比例。 5、流动性管理策略在满足基金投资者申购、赎回的资金需求前提下,通过基金资产安排(包括现金库存、资产变现、剩余期限管理或以其他措施),在保持基金资产高流动性的前提下,确保基金的稳定收益。 6、无风险套利策略无风险套利策略包括: 跨市场套利策略:根据各细分短期金融工具的流动性和收益特征,动态调整基金资产在各个细分市场之间的配置比例。如,当交易所市场回购利率高于银行间市场回购利率时,可增加交易所市场回购的配置比例;另外,还包括一级市场发行定价和二级市场流通成交价之间的无风险套利机会。跨品种套利策略:根据各细分市场中不同品种的风险参数、流动性补偿和收益特征,动态调整不同期限结构品种的配置比例。 7、滚动配置策略根据具体投资品种的市场特性,采用持续滚动投资的方法,以提高基金资产的整体持续的变现能力。 8、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向,一旦监管机构允许货币市场基金参与此类金融工具的投资,基金管理人在履行适当程序后将其纳入投资范围,本基金将在届时相应法律法规的框架内,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000559', '诺安天天宝A', '货币市场型基金', 98438663424.1, '2014-03-25', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将在深入研究国内外的宏观经济走势、货币政策变化趋势、市场资金供求状况的基础上,分析和判断利率走势与收益率曲线变化趋势,并综合考虑各类投资品种的收益性、流动性和风险特征,对基金资产组合进行积极管理。 1、利率预期策略影响利率走势的因素很多,影响短期利率变动的因素更多,运行方式也更为复杂。基金管理人将重点考察以下两个因素: (1)中央银行、财政部等国家宏观经济管理部门的政策意图。政府对金融市场运行的影响非常深远。国家宏观经济管理部门尤其是中央银行对经济运行形势的判断及采取的应对政策是影响市场利率走势的关键因素之一。 (2)短期资金供求变化。短期资金市场参与者的头寸宽紧程度是短期利率变动的重要主导力量。短期利率随短期资金供求变化呈一定的季节波动形态。具体而言,本基金管理人将持续跟踪反映国民经济变化的宏观经济指标,对国家经济政策进行深入分析,进而对短期利率的变化态势做出及时反应。重点关注的宏观经济指标包括:国家经济管理部门政策、预期物价指数、相关市场资金供求关系等等。在分析方法上,本基金管理人坚持定性与定量相结合的分析方法。 2、期限配置策略在短期利率期限结构分析的基础上,根据对投资对象流动性和收益性的动态考察,构建合理期限结构的投资组合。从组合总的剩余期限结构来看,一般说来,预期利率上涨时,将适当缩短组合的平均期限;预期利率下降时,将在法律法规允许的范围内适当延长组合的平均剩余期限。 3、品种配置策略在短期利率期限结构分析和品种深入分析的基础上,进行品种合理配置。当预期利率上涨时,可以增加回购资产的比重,适度降低债券资产的比重;预期利率下降,将降低回购资产的比重,增加债券资产的比重。 4、银行定期存款及大额存单投资策略银行定期存款及大额存单是本基金的主要投资对象,因此,银行定期存款及大额存单的投资将是本基金关注的重点之一。具体而言,在组合投资过程中,本基金将在综合考虑成本收益的基础上,尽可能的扩大交易对手方的覆盖范围,通过对这些银行广泛、耐心而细致的询价,挖掘出利率报价较高的多家银行进行银行定期存款及大额存单的投资,在获取较高投资收益的同时尽量分散投资风险,提高存款及存单资产的流动性。 5、套利策略在久期控制的基础上,本基金管理人将对货币市场的各个细分市场进行深入研究分析,在严格控制风险和保障流动性的前提下,寻找跨市场、跨期限、跨品种的套利投资机会,以期获得更高的收益。当然,由于交易机制的限制,目前挖掘套利投资机会的投资方法主要是用风险相当,但收益更高的品种替代收益较低的品种,或者用收益相当,风险较低的品种替代风险较高的品种。 6、流动性管理策略流动性好是货币市场基金的重要特征之一。在日常的投资管理过程中,本基金将会紧密关注申购/赎回现金流变化情况、季节性资金流动等影响货币市场基金流动性管理的因素,建立组合流动性监控管理指标,实现对基金资产流动性的实时管理。具体而言,本基金将综合平衡基金资产在流动性资产和收益性资产之间的配置比例,通过现金留存、银行定期存款提前支取、持有高流动性券种、正向回购、降低组合久期等方式提高基金资产整体的流动性,也可采用持续滚动投资方法,将回购或债券的到期日进行均衡等量配置,以满足日常的基金资产变现需求。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000687', '南方薪金宝A', '货币市场型基金', 94485626859.94, '2014-06-23', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采用积极管理型的投资策略,在控制利率风险、尽量降低基金净值波动风险并满足流动性的前提下,提高基金收益。 1、利率策略本基金将首先采用“自上而下”的研究方法,综合研究主要经济变量指标、分析宏观经济情况,建立经济前景的情景模拟,进而判断财政政策、货币政策等宏观经济政策取向。同时,本基金还将分析金融市场资金供求状况变化趋势,对影响资金面的因素进行详细分析与预判,建立资金面的场景模拟。在宏观分析与流动性分析的基础上,结合历史与经验数据,确定当前资金的时间价值、通货膨胀补偿、流动性溢价等要素,得到当前宏观与流动性条件下的均衡收益率曲线。区分当前利率债收益率曲线期限利差、曲率与券间利差所面临的历史分位,然后通过市场收益率曲线与均衡收益率曲线的对比,判断收益率曲线参数变动的程度和概率,确定组合的平均剩余期限,并据此动态调整投资组合。 2、骑乘策略当市场利率期限结构向上倾斜并且相对较陡时,投资并持有债券一段时间,随着时间推移,债券剩余年限减少,市场同样年限的债券收益率较低,这时将债券按市场价格出售,投资人除了获得债券利息以外,还可以获得资本利得。在多数情况下,这样的骑乘操作策略可以获得比持有到期更高的收益。 3、放大策略放大策略即以组合现有债券为基础,利用买断式回购、质押式回购等方式融入资金,并购买剩余年限相对较长的债券,以期获取超额收益的操作方式。在回购利率过高、流动性不足、或者市场状况不宜采用放大策略等情况下,本基金将适时降低杠杆投资比例。 4、信用债投资策略 (1)信用风险控制。本基金拟投资的每支信用债券必需经过南方基金债券信用评级系统进行内部评级,符合基金所对应的内部评级规定的方可进行投资,以事前防范和控制信用风险。 (2)信用利差策略。信用产品相对国债、政策性金融债等利率产品的信用利差是获取较高投资收益的来源。首先,伴随经济周期的波动,在经济周期上行或下行阶段,信用利差通常会缩小或扩大,利差的变动会带来趋势性的信用产品投资机会。同时,研究不同行业在经济周期和政策变动中所受的影响,以确定不同行业总体信用风险和利差水平的变动情况,投资具有积极因素的行业,规避具有潜在风险的行业。其次,信用产品发行人资信水平和评级调整的变化会使产品的信用利差扩大或缩小,本基金将充分发挥内部评级在定价方面的作用,选择评级有上调可能的信用债,以获取因利差下降带来的价差收益。第三,对信用利差期限结构进行研究,分析各期限信用债利差水平相对历史平均水平所处的位置,以及不同期限之间利差的相对水平,发现更具投资价值的期限进行投资;第四,研究分析相同期限但不同信用评级债券的相对利差水平,发现偏离均值较多、相对利差有收窄可能的债券。 (3)类属选择策略。国内信用产品目前正经历着快速发展阶段,不同审批机构批准发行的信用产品在定价、产品价格特性、信用风险方面具有一定差别,本基金将考虑产品定价的合理性、产品主要投资人的需求特征、不同类属产品的持有收益和价差收益特点和实际信用风险状况,进行信用债券的类属选择。 5、资产支持证券投资策略当前国内资产支持证券市场以信贷资产证券化产品为主(包括以银行贷款资产、住房抵押贷款等作为基础资产),仍处于创新试点阶段。产品投资关键在于对基础资产质量及未来现金流的分析,本基金将在国内资产证券化产品具体政策框架下,采用基本面分析和数量化模型相结合,对个券进行风险分析和价值评估后进行投资。本基金将严格控制资产支持证券的总体投资规模并进行分散投资,以降低流动性风险。 6、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向,一旦监管机构允许基金参与此类金融工具的投资,本基金将在届时相应法律法规的框架内,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('004217', '兴业安润B', '货币市场型基金', 89634431158.48, '2017-01-06', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金根据对短期利率变动的预测，采用投资组合平均剩余期限控制下的主动性投资策略，利用定性分析和定量方法，在控制风险和保证流动性的基础上，力争获得稳定当益。INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000816', '南方理财金A', '货币市场型基金', 89389879361.19, '2014-12-05', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采用积极管理型的投资策略,在控制利率风险、尽量降低基金净值波动风险并满足流动性的前提下,提高基金收益。1、利率策略本基金将首先采用“自上而下”的研究方法,综合研究主要经济变量指标、分析宏观经济情况,建立经济前景的情景模拟,进而判断财政政策、货币政策等宏观经济政策取向。同时,本基金还将分析金融市场资金供求状况变化趋势,对影响资金面的因素进行详细分析与预判,建立资金面的场景模拟。在宏观分析与流动性分析的基础上,结合历史与经验数据,确定当前资金的时间价值、通货膨胀补偿、流动性溢价等要素,得到当前宏观与流动性条件下的均衡收益率曲线。区分当前利率债收益率曲线期限利差、曲率与券间利差所面临的历史分位,然后通过市场收益率曲线与均衡收益率曲线的对比,判断收益率曲线参数变动的程度和概率,确定组合的平均剩余期限,并据此动态调整投资组合。2、骑乘策略当市场利率期限结构向上倾斜并且相对较陡时,投资并持有债券一段时间,随着时间推移,债券剩余年限减少,市场同样年限的债券收益率较低,这时将债券按市场价格出售,投资人除了获得债券利息以外,还可以获得资本利得。在多数情况下,这样的骑乘操作策略可以获得比持有到期更高的收益。3、放大策略放大策略即以组合现有债券为基础,利用买断式回购、质押式回购等方式融入资金,并购买剩余年限相对较长的债券,以期获取超额收益的操作方式。在回购利率过高、流动性不足、或者市场状况不宜采用放大策略等情况下,本基金将适时降低杠杆投资比例。4、信用债投资策略(1)信用风险控制。本基金拟投资的每支信用债券必需经过南方基金债券信用评级系统进行内部评级,符合基金所对应的内部评级规定的方可进行投资,以事前防范和控制信用风险。(2)信用利差策略。信用产品相对国债、政策性金融债等利率产品的信用利差是获取较高投资收益的来源。首先,伴随经济周期的波动,在经济周期上行或下行阶段,信用利差通常会缩小或扩大,利差的变动会带来趋势性的信用产品投资机会。同时,研究不同行业在经济周期和政策变动中所受的影响,以确定不同行业总体信用风险和利差水平的变动情况,投资具有积极因素的行业,规避具有潜在风险的行业。其次,信用产品发行人资信水平和评级调整的变化会使产品的信用利差扩大或缩小,本基金将充分发挥内部评级在定价方面的作用,选择评级有上调可能的信用债,以获取因利差下降带来的价差收益。第三,对信用利差期限结构进行研究,分析各期限信用债利差水平相对历史平均水平所处的位置,以及不同期限之间利差的相对水平,发现更具投资价值的期限进行投资;第四,研究分析相同期限但不同信用评级债券的相对利差水平,发现偏离均值较多、相对利差有收窄可能的债券。(3)类属选择策略。国内信用产品目前正经历着快速发展阶段,不同审批机构批准发行的信用产品在定价、产品价格特性、信用风险方面具有一定差别,本基金将考虑产品定价的合理性、产品主要投资人的需求特征、不同类属产品的持有收益和价差收益特点和实际信用风险状况,进行信用债券的类属选择。5、资产支持证券投资策略当前国内资产支持证券市场以信贷资产证券化产品为主(包括以银行贷款资产、住房抵押贷款等作为基础资产),仍处于创新试点阶段。产品投资关键在于对基础资产质量及未来现金流的分析,本基金将在国内资产证券化产品具体政策框架下,采用基本面分析和数量化模型相结合,对个券进行风险分析和价值评估后进行投资。本基金将严格控制资产支持证券的总体投资规模并进行分散投资,以降低流动性风险。6、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向,一旦监管机构允许基金参与此类金融工具的投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000581', '嘉实活钱包A', '货币市场型基金', 86725146729.47, '2014-03-17', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1、资产配置策略根据宏观经济指标(主要包括:市场资金供求、利率水平和市场预期、通货膨胀率、GDP增长率、货币供应量、就业率水平、国际市场利率水平、汇率等),决定组合的平均剩余期限(长/中/短)和比例分布。根据各类资产的流动性特征(主要包括:平均日交易量、交易场所、机构投资者持有情况、回购抵押数量等),决定组合中各类资产的投资比例。根据各类资产的信用等级及担保状况,决定组合的风险级别。 2、个券选择策略在个券选择上,本基金通过定性定量方法,综合分析收益率曲线、流动性、信用风险,评估个券投资价值,发掘出具备相对价值的个券。 3、银行存款投资策略本基金根据不同银行的银行存款收益率情况,结合银行的信用等级、存款期限等因素的分析,以及对整体利率市场环境及其变动趋势的研究,在严格控制风险的前提下选择具有较高投资价值的银行存款进行投资。 4、利用短期市场机会的灵活策略由于市场分割、信息不对称、发行人信用等级意外变化等情况会造成短期内市场失衡;新股、新债发行以及年末效应等因素会使市场资金供求发生短时的失衡。这种失衡将带来一定市场机会。通过分析短期市场机会发生的动因,研究其中的规律,据此调整组合配置,改进操作方法,积极利用市场机会获得超额收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000725', '大成添利宝B', '货币市场型基金', 86511858597.71, '2014-07-28', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1、利率趋势评估策略通过对宏观经济、宏观政策、市场资金面供求等因素的综合分析,对资金利率变动趋势进行评估,最大限度地优化存款期限、回购和债券品种组合。 2、类属配置策略本基金管理人在评估各品种在流动性、收益率稳定性基础上,结合预先制定的组合平均期限范围确定类属资产配置。 3、组合平均剩余期限配置策略基金根据对未来短期利率走势的研判,结合基金资产流动性的要求动态调整组合久期。当预期短期利率上升时,降低组合久期,以规避资本损失或获得较高的再投资收益;在预期短期利率下降时,提高组合久期,以获得资本利得或锁定较高的利率水平。 4、银行协议存款和大额存单投资策略银行协议存款和大额存单是本基金的主要投资对象。在确保安全性和流动性的前提下,通过不同商业银行和不同存款期限的选择,挖掘出利率报价较高的多家银行进行银行协议存款和大额存单的投资,在获取较高投资收益的同时尽量分散投资风险,提高存款及存单资产的流动性。通过对宏观经济、宏观政策、市场资金面等因素的综合分析,对资金利率变动趋势进行评估,最大限度地优化存款期限。 5、流动性管理策略在日常的投资管理过程中,本基金将会紧密关注申购与赎回资金变化情况、季节性资金流动等影响货币市场基金流动性管理的因素,建立组合流动性监控管理指标,实现对基金资产流动性的实时管理。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000759', '平安财富宝A', '货币市场型基金', 85023210539.16, '2014-08-21', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金根据对未来短期利率变动的预测,确定和调整基金投资组合的平均剩余期限。对各类投资品种进行定性分析和定量分析方法,确定和调整参与的投资品种和各类投资品种的配置比例。在严格控制投资风险和保持资产流动性的基础上,力争获得稳定的当期收益。 1、整体资产配置策略 本基金通过对宏观经济形势、财政与货币政策、金融监管政策、短期资金市场状况等因素的分析,综合判断未来短期利率变动,对投资组合的平均剩余期限进行控制。 (1)利率预期分析 通过对通货膨胀、GDP、货币供应量、国际利率水平、金融监管政策取向等跟踪分析,形成对基本面的宏观研判。同时,结合微观层面研究,主要考察指标包括:央行公开市场操作、主要机构投资者的短期投资倾向、债券供给、回购抵押数量等,合理预期货币市场利率曲线动态变化。 (2)动态调整投资组合平均剩余期限 根据利率预期分析,动态确定并控制投资组合平均剩余期限在120天以内。当市场利率看涨时,适度缩短投资组合平均剩余期限,即减持剩余期限较长投资品种增持剩余期限较短品种,降低组合整体净值损失风险;当市场看跌时,则相对延长投资组合平均剩余期限,增持较长剩余期限的投资品种,获取超额收益。 2、类属资产配置策略 类属资产配置指投资组合在各类投资品种如央行票据、国债、金融债、企业短期融资券以及现金等投资品种之间的配置比例。作为现金管理工具本基金将根据各类投资品种的流动性、收益性和风险特征,利用定性分析和定量分析方法,决定参与的投资品种和各类投资品种的配置比例及投资品种期限组合。 (1)流动性分析 通过对市场资金面、基金申购赎回金额的变化进行动态分析,确定本基金的流动性目标。在此基础上,基金管理人在高流动性资产和相对流动性较低资产之间寻找平衡,以满足组合的日常流动性需求。 (2)收益-风险分析 通过分析各类投资品种的相对收益、利差变化、市场容量、信用等级情况、流动性风险、信用风险等因素来确定配置比例和期限组合,寻找具有投资价值的投资品种,增持相对低估、价格将上升的,能给组合带来相对较高回报的类属;减持相对高估、价格将下降的,给组合带来相对较低回报的类属,借以取得较高的总回报。 3、个券选择策略 在个券选择层面,本基金将首先从安全性角度出发,优先选择央票、短期国债等高信用等级的债券品种以规避信用违约风险。对于信用评级等级较高(符合法规规定的级别)的企业债、短期融资券等信用类债券,本基金也可以进行配置。除考虑安全性因素外,在具体的券种选择上,基金管理人将遵循以下原则: (1)根据明细资产的剩余期限、资信等级、流动性指标(流通总量、日均交易量),决定是否纳入组合; (2)根据个别债券的收益率(到期收益率、票面利率、利息支付方式、利息税务处理)与剩余期限的配比,对照基金的收益要求决定是否纳入组合; (3)根据个别债券的流动性指标(发行总量、流通量、上市时间),决定投资总量。 (4)若出现因市场原因所导致的收益率高于公允水平,则该券种价格出现低估,本基金将对此类低估品种进行重点关注。 4、流动性管理策略 本基金作为现金管理工具,必须具备较高的流动性。基金管理人在密切关注基金的申购赎回情况、季节性资金流动情况和日历效应等因素基础上,对投资组合的现金比例进行优化管理。基金管理人将在遵循流动性优先的原则下,综合平衡基金资产在流动性资产和收益性资产之间的配置比例,通过现金留存、持有高流动性券种、正向回购、降低组合久期等方式提高基金资产整体的流动性,以满足日常的基金资产变现需求。 5、套利策略 由于市场环境差异、交易市场分割、市场参与者差异,以及资金供求失衡导致的中短期利率异常差异,使得债券现券市场上存在着套利机会。本基金通过分析货币市场变动趋势、各市场和品种之间的风险收益差异,把握无风险套利机会,包括银行间和交易所市场出现的跨市场套利机会、在充分论证套利可行性的基础上的跨期限套利等。基金管理人将在保证基金的安全性和流动性的前提下,适当参与市场的套利,捕捉和把握无风险套利机会,进行跨市场、跨品种操作,以期获得安全的超额收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('009824', '鹏华添利宝B', '货币市场型基金', 81808397903.8, '2020-08-14', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将综合宏观经济运行状况,货币政策、财政政策等政府宏观经济状况及政策,分析资本市场资金供给状况的变动趋势,预测市场利率水平变动趋势。在此基础上,综合考虑各类投资品种的流动性、收益性以及信用风险状况,进行积极的投资组合管理。 1、久期策略结合宏观经济运行态势及利率预测分析,本基金将动态确定并调整基金组合平均剩余期限。预测利率将进入下降通道时,适当延长投资品种的平均期限;预测市场利率将进入上升通道时,适当缩短投资品种的平均期限。 2、类属配置策略在保证流动性的前提下,根据各类货币市场工具的市场规模、信用等级、流动性、市场供求、票息及付息频率等确定不同类别资产的具体配置比例。 3、套利策略本基金根据对货币市场变动趋势、各市场和品种之间的风险收益差异的充分研究和论证,适当进行跨市场或跨品种套利操作,力争提高资产收益率,具体策略包括跨市场套利和跨期限套利等。 4、现金管理策略本基金作为现金管理工具,具有较高的流动性要求,本基金将根据对市场资金面分析以及对申购赎回变化的动态预测,通过回购的滚动操作和债券品种的期限结构搭配,动态调整并有效分配基金的现金流,在保持充分流动性的基础上争取较高收益。 5、资产支持证券的投资策略本基金将综合运用战略资产配置和战术资产配置进行资产支持证券的投资组合管理,并根据信用风险、利率风险和流动性风险变化积极调整投资策略,严格遵守法律法规和基金合同的约定,在保证本金安全和基金资产流动性的基础上获得稳定收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('001526', '鑫元安鑫宝货币A', '货币市场型基金', 80523788609.91, '2015-06-26', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1、整体资产配置策略 本基金采取积极的投资策略,自上而下地进行投资管理。通过定性分析和定量分析,形成对短期利率变化方向的预测;在此基础之上,确定组合久期和类别资产配置比例;在此框架之下,通过把握收益率曲线形变和无风险套利机会来进行品种选择。 2、类属资产配置策略 类属资产配置是指基金组合在国债、央行票据、债券回购、金融债、短期融资券及现金等投资品种之间的配置比例。通过对各类别金融工具政策倾向、税收政策、信用等级、收益率水平、资金供求、流动性等因素的研究判断,采用相对价值和信用利差策略,挖掘不同类别金融工具的差异化投资价值,合理配置并灵活调整不同类属债券在组合中的构成比例,形成合理组合以实现稳定的投资收益。 3、个券选择策略在确定债券平均组合久期、期限结构配置和类属配置的基础上,对影响个别债券定价的主要因素,包括信用风险、流动性、市场供求、票息及付息频率、税赋、含权等因素进行分析,有限选择央票、短期国债等高等级债券品种以规避违约风险,在此基础上通过拟合收益率曲线寻找定价低估、收益率偏高的券种进行重点关注。本基金投资证券公司短期公司债券,基金管理人将根据审慎原则,指定严格的投资决策流程和风险控制制度,以防范信用风险、流动性风险等各种风险。投资证券公司短期公司债券的关键在于系统分析和跟踪证券公司的基本面情况,本基金主要通过定量与定性相结合的研究及分析方法进行投资证券公司短期公司债券的选择和投资。定量分析方面,基金管理人将着重关注债券发行人的财务状况,包括发行主体的偿债能力、盈利能力、现金流获取能力以及发行主体的长期资本结构等。定性分析则重点关注所发行债券的具体条款以及发行主体情况。 4、回购策略 该策略是利用回购利率低于债券收益率的机会通过循环回购以放大债券投资收益的投资策略。该策略的基本模式是利用买入债券进行正回购,在利用回购融入资金购买收益率较高债券品种,如此循环至回购期结束卖出债券偿还所融入资金。在进行回购放大操作时,基金管理人将严格遵守相关法律法规关于债券正回购的有关规定。基金管理人也将密切关注由于新股申购等原因导致短期资金需求激增的机会,通过逆回购的方式融出资金以分享短期资金利率陡升的投资机会。 5、收益率曲线策略 根据债券市场收益率曲线的动态变化以及隐含的即期利率和远期利率提供的价值判断基础,结合对当期和远期资金面的分析,寻求在一段时期内获取因收益率曲线变化而导致的债券价格变化所产生的超额收益。本基金将比较分析子弹策略、哑铃策略和梯形策略等在不同市场环境下的表现,构建优化组合,获取合理收益。 6、流动性管理策略本基金作为现金管理工具,具有较高的流动性要求。根据对市场资金面分析以及对申购赎回变化的动态预测,基金管理人通过对市场结构、市场冲击情况、主要资产流动性变化跟踪分析等多种方式对流动性进行定量定性分析,在兼顾基金收益的前提下合理地控制资产的流动性风险,综合平衡基金资产在流动性资产和收益性资产之间的配置比例,通过现金留存、持有高流动性券种、正向回购、降低组合久期等方式提高基金资产整体的流动性。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000760', '工银财富快线A', '货币市场型基金', 78307315969.38, '2015-06-19', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将采取利率策略、信用策略、相对价值策略等积极投资策略,在严格控制风险的前提下,发掘和利用市场失衡提供的投资机会,实现组合增值。 1、利率策略通过全面研究GDP、物价、就业以及国际收支等主要经济变量,分析宏观经济运行的可能情景,并预测财政政策、货币政策等宏观经济政策取向,分析金融市场资金供求状况变化趋势及结构。在此基础上,预测金融市场利率水平变动趋势,以及金融市场收益率曲线斜度变化趋势。 2、信用策略根据国民经济运行周期阶段,分析债券发行人所处行业发展前景、发展状况、市场地位、财务状况、管理水平和债务水平等因素,评价债券发行人的信用风险。跟踪债券发行人和债券工具自身的信用质量变化,并结合外部权威评级机构的信用评级结果,确定基金资产对相应债券的投资决策。 3、类属配置策略 研究国民经济运行状况,货币市场及资本市场资金供求关系,以及不同时期市场投资热点,分析国债、金融债、企业债券等不同债券种类的利差水平,评定不同债券类属的相对投资价值,确定组合资产在不同债券类属之间配置比例。 4、个券选择策略本基金认为普通债券的估值,主要基于收益率曲线的拟合。在正确拟合收益率曲线的基础上,及时发现偏离市场收益率的债券,并找出因投资者偏好、供求、流动性、信用利差等导致债券价格偏离的原因;同时,基于收益率曲线判断出定价偏高或偏低的期限段,从而指导相对价值投资,选择出估值较低的债券品种。对于含回售条款的债券,本基金将仅买入距回售日不超过397天以内的债券,并在回售日前进行回售或者卖出。 5、相对价值策略本基金认为市场普遍存在着失效的现象,短期因素的影响被过分夸大。债券市场的参与者众多,投资行为、风险偏好、财务与税收处理等各不相同,发掘存在于这些不同因素之间的相对价值,也是本基金发现投资机会的重要方面。本基金密切关注国家法律法规、制度的变动,通过深入分析市场参与者的立场和观点,充分利用因市场分割、市场投资者不同风险偏好或者税收待遇等因素导致的市场失衡机会,形成相对价值投资策略,运用回购、远期交易合同等交易工具进行不同期限、不同品种或不同市场之间的套利交易,为本基金的投资带来增加价值。 6、资产支持证券投资策略当前国内资产支持证券主要为以银行贷款资产、住房抵押贷款等作为基础资产的信贷资产证券化产品,本基金侧重于对基础资产质量及未来现金流的分析,采用基本面分析和数量化模型相结合,对个券进行风险分析和价值评估后进行投资。本基金将严格控制资产支持证券的投资比例、信用等级并密切跟踪评级变化,采用分散投资方式以降低流动性风险。 7、其他金融工具投资策略本基金将密切跟踪银行承兑汇票、商业承兑汇票等商业票据以及各种衍生产品的动向。当法律法规允许基金参与此类金融工具的投资,本基金将按照届时生效的法律法规,根据对该金融工具的研究,制定符合本基金投资目标的投资策略,在充分考虑该投资品种风险和收益特征的前提下,谨慎投资。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('004545', '永赢天天利A', '货币市场型基金', 77123624859.83, '2017-04-20', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '1、货币市场利率研判与管理策略货币市场利率研判与管理策略是本基金的基本投资策略。根据对宏观经济指标、财政与货币政策和市场资金供求等因素的研究与分析，对未来一段时期的货币市场利率进行研究判断，并根据研究结论制定和调整组合的期限和品种配置，追求更高收益。2、期限配置策略根据对货币市场利率与投资人流动性需求的判断，确定并调整组合的平均期限。在预期货币市场利率上升时或投资人赎回需求提高时，缩短组合的平均期限，以规避资本损失或获得较高的再投资收益和满足投资人流动性需求；在预期短期利率下降时或投资人申购意愿提高时，延长组合的平均期限，以获得资本利得或锁定较高的利率水平和为投资人潜在投资需求提前做准备。3、类属和品种配置策略在保持组合资产相对稳定的条件下，根据各类短期金融工具的不同流动性特征、收益特征和市场规模，制定并调整类属和品种配置策略，在保证组合的流动性要求的基础上，提高组合的收益性。4、资产支持证券投资策略本基金将综合运用定性方法和定量方法，基本面分析和数量化模型相结合，对资产证券化产品的基础资产质量及未来现金流进行分析，并结合发行条款、提前偿还率、风险补偿收益等个券因素以及市场利率、流动性等影响资产支持证券价值的因素进行分析和价值评估后进行投资。本基金将严格遵守法律法规和基金合同的约定，严格控制资产支持证券的投资比例、信用等级并密切跟踪评级变化，采用分散投资方式以降低流动性风险。5、灵活的交易策略由于新股、新债发行以及年末、季末效应等因素，以及投资人对信息可能产生的过度反应都会使市场资金供求发生短时的失衡。这种失衡将带来一定市场机会。通过研究其动因，可以更有效地获得市场失衡带来的投资收益。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('005253', '国泰货币B', '货币市场型基金', 76920844653.69, '2020-05-29', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金主要为投资者提供流动性现金管理工具,主要结合短期利率变动,合理安排债券组合期限和类属比例,在保证本金安全性、流动性的前提下,获得超过基准的较高收益。根据对宏观经济指标长期趋势的判断、市场预期相对于无目的地偏离的程度和各类金融工具的流动性特征,决定组合中债券与其他资产的比例颁布。考虑法律法规的相关规定、各类属资产的到期收益率、税收、相对收益差额及不同类属资产的流动性指标等因素决定债券组合的类属配置。通过期限配置和收益率曲线配置来建立债券组合。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
INSERT INTO fund_detail (fund_code, fund_name, invest_type, net_asset_yuan, setup_date, latest_nav, latest_acc_nav, latest_nav_date, invest_style, risk_level, invest_strategy) VALUES ('000874', '华安现金宝B', '货币市场型基金', 72988491476.78, '2017-03-10', 1.0, 0.0, '2026-09-18', '货币型', 'R1-低风险', '本基金将根据市场情况和可投资品种的容量，在严谨深入的研究分析基础上，综合考量宏观经济形势、市场资金面走向、信用债券的信用评级、协议存款交易对手的信用资质以及各类资产的收益率水平等，确定各类货币市场工具的配置比例并进行积极的投资组合管理，在保证基金资产的安全性和流动性的基础上力争为投资人创造稳定的收益。1、整体资产配置策略根据宏观经济指标(通货膨胀率、GDP增长率、货币供应量、就业率水平、利率水平和市场预期、汇率等)、央行货币政策和市场资金供求状况，进行大势研判、形成货币市场收益率曲线预期并据此确定组合的平均剩余期限和各期限品种比例分布。比如，根据历史上我国短期资金市场利率的走势，在年初、年末资金利率较高时按哑铃策略配置基金资产，而在年中资金利率偏低时则按梯形策略配置基金资产。2、类属资产配置策略根据各类货币市场工具的市场收益率水平(持有期收益率、到期收益率、票面利率、利息支付方式、利息税务处理、附加选择权价值、类别资产收益差异等)和利差变化，确定优先配置的资产类别。同时，结合各类资产的流动性特征(市场容量、平均日交易量、交易场所、机构投资者持有情况、回购抵押数量等)，决定组合中各类资产的配置比例。3、个券选择策略在个券选择层面，本基金将首先从安全性角度出发，优先选择央票、短期国债等利率品种以回避信用风险。对于信用资质较高的信用类品种，本基金也可择优配置。具体来说，基金管理人将通过“华安信用评级模型”对市场公开发行的所有短期融资券、中期票据、企业债等信用债券进行独立的内部评级，形成2-5级的内部评级结果，3级以上(含)为可投资范围。在具体券种的选择上，基金管理人将在正确拟合收益率曲线的基础上，从合格的投资范围中找出收益率明显偏高的券种，并客观分析收益率出现偏离的原因，判别出因市场因素导致真正低估的个券进行重点关注。对于含有回售条款的债券，本基金将仅买入距回售日不超过397天以内的债券，并在回售日进行回售或在回售日前卖出。4、流动性管理策略在流动性优先的原则下，本基金将综合平衡基金资产在流动性资产和收益性资产之间的配置比例，通过现金留存、持有高流动性券种、正向回购、降低组合久期等方式保持较高的资产组合整体流动性。同时，基金管理人将密切关注基金的申购赎回情况、季节性资金流动情况和日历效应等因素，对投资组合的现金比例进行结构化管理。此外，基金还可根据回购等具体投资品种的市场特性，采用持续滚动投资等方式以提高基金资产的整体变现能力。随着证券市场的发展和投资工具的丰富，本基金将在届时有效的法律法规的框架内，制订相应的符合本基金投资目标的投资策略或对现有投资策略进行调整更新，并在更新的招募说明书中予以披露。') ON CONFLICT (fund_code) DO UPDATE SET fund_name=EXCLUDED.fund_name, invest_type=EXCLUDED.invest_type, net_asset_yuan=EXCLUDED.net_asset_yuan, setup_date=EXCLUDED.setup_date, latest_nav=EXCLUDED.latest_nav, latest_acc_nav=EXCLUDED.latest_acc_nav, latest_nav_date=EXCLUDED.latest_nav_date, invest_style=EXCLUDED.invest_style, risk_level=EXCLUDED.risk_level, invest_strategy=EXCLUDED.invest_strategy;
